// Makine Bölümü Quiz Soruları — devam bankası (her konu için id 51..150)
import type { QuizQuestion } from "@/types/quiz";

export const machineQuizQuestionsExt2: Record<string, QuizQuestion[]> = {
  electrical: [
    { id: 51, question: "24 V gerilim altında 6 Ω'luk bir dirençten geçen akım kaç A'dir?", options: ["6 A", "8 A", "2 A", "4 A"], correctAnswer: 3, explanation: "I = V/R = 24/6 = 4 A.", category: "Gemi Elektrik" },
    { id: 52, question: "220 V'ta 11 A çeken bir yükün gücü kaç W'dır?", options: ["1,980 W", "2,200 W", "2,420 W", "2,640 W"], correctAnswer: 2, explanation: "P = V·I = 220 · 11 = 2,420 W.", category: "Gemi Elektrik" },
    { id: 53, question: "Direnci 8 Ω olan bir elemandan 5 A akım geçerse harcanan güç kaç W'dır?", options: ["200 W", "320 W", "40 W", "120 W"], correctAnswer: 0, explanation: "P = I²·R = 25 · 8 = 200 W.", category: "Gemi Elektrik" },
    { id: 54, question: "440 V üç fazlı bir motor 30 A çekiyor ve cosφ = 0.85 ise aktif güç kaç kW'dır?", options: ["22.9 kW", "26.4 kW", "15.4 kW", "19.4 kW"], correctAnswer: 3, explanation: "P = √3 · V · I · cosφ = 1.732 · 440 · 30 · 0.85 ≈ 19,430 W ≈ 19.4 kW.", category: "Gemi Elektrik" },
    { id: 55, question: "Aynı motorun görünür gücü kaç kVA'dır?", options: ["26.4 kVA", "16.5 kVA", "19.4 kVA", "22.9 kVA"], correctAnswer: 3, explanation: "S = √3 · V · I = 1.732 · 440 · 30 ≈ 22,860 VA ≈ 22.9 kVA.", category: "Gemi Elektrik" },
    { id: 56, question: "22.9 kVA görünür güç ve 19.4 kW aktif güç için reaktif güç yaklaşık kaç kVAr'dır?", options: ["3.5 kVAr", "7.6 kVAr", "12.1 kVAr", "16.4 kVAr"], correctAnswer: 2, explanation: "Q = √(S² − P²) = √(22.9² − 19.4²) = √(524 − 376) = √148 ≈ 12.1 kVAr.", category: "Gemi Elektrik" },
    { id: 57, question: "Güç faktörünün düşük olması gemi elektrik sisteminde neye yol açar?", options: ["Frekansın artmasına", "Yalıtımın iyileşmesine", "Gerilimin yükselmesine", "Aynı aktif güç için daha yüksek akım ve daha büyük kayıplara"], correctAnswer: 3, explanation: "Düşük cosφ, kablo ve jeneratörde gereksiz akım dolaştırır; ısı kaybı ve gerilim düşümü artar.", category: "Gemi Elektrik" },
    { id: 58, question: "Güç faktörü düzeltmesinde tipik olarak ne kullanılır?", options: ["Direnç", "Kondansatör bataryası", "Bobin", "Diyot"], correctAnswer: 1, explanation: "Endüktif yüklerin (motorlar) çektiği reaktif gücü kapasitif reaktif güçle dengeleyerek cosφ 1'e yaklaştırılır.", category: "Gemi Elektrik" },
    { id: 59, question: "Üç fazlı yıldız bağlantıda faz gerilimi ile hat gerilimi arasındaki ilişki nedir?", options: ["Hat gerilimi = √3 × faz gerilimi", "Hat gerilimi = 3 × faz gerilimi", "Faz gerilimi = 3 × hat gerilimi", "Eşittir"], correctAnswer: 0, explanation: "Yıldızda hat akımı faz akımına eşit, hat gerilimi ise faz geriliminin √3 katıdır.", category: "Gemi Elektrik" },
    { id: 60, question: "Faz gerilimi 254 V olan yıldız bağlı sistemde hat gerilimi yaklaşık kaç V'tur?", options: ["660 V", "220 V", "380 V", "440 V"], correctAnswer: 3, explanation: "V hat = √3 · 254 ≈ 1.732 · 254 ≈ 440 V.", category: "Gemi Elektrik" },
    { id: 61, question: "Üçgen (delta) bağlantıda hat akımı ile faz akımı arasındaki ilişki nedir?", options: ["Faz akımı = √3 × hat akımı", "Eşittir", "Hat akımı = √3 × faz akımı", "Hat akımı = 3 × faz akımı"], correctAnswer: 2, explanation: "Üçgende hat gerilimi faz gerilimine eşit, hat akımı ise faz akımının √3 katıdır.", category: "Gemi Elektrik" },
    { id: 62, question: "Yıldız-üçgen yol vermenin amacı nedir?", options: ["Momenti artırmak", "Verimi artırmak", "Devri artırmak", "Kalkış akımını azaltmak"], correctAnswer: 3, explanation: "Yıldızda sargı gerilimi düşer; kalkış akımı ve momenti yaklaşık üçte bire iner, motor hızlanınca üçgene geçilir.", category: "Gemi Elektrik" },
    { id: 63, question: "Yıldız-üçgen yol vermede kalkış momenti nasıl değişir?", options: ["Yaklaşık üçte birine iner", "İki katına çıkar", "Sıfır olur", "Değişmez"], correctAnswer: 0, explanation: "Moment gerilimin karesiyle orantılıdır; bu yüzden yüksek kalkış momenti gerektiren yüklerde bu yöntem uygun değildir.", category: "Gemi Elektrik" },
    { id: 64, question: "Bir transformatörün primer sarım sayısı 400, sekonder 100 ve primer gerilimi 440 V ise sekonder gerilimi kaç V'tur?", options: ["220 V", "1,760 V", "55 V", "110 V"], correctAnswer: 3, explanation: "V2 = V1 · (N2/N1) = 440 · (100/400) = 110 V.", category: "Gemi Elektrik" },
    { id: 65, question: "Kayıpsız kabul edilen bir transformatörde sekonder akımı primerin kaç katıdır? (dönüştürme oranı 4:1)", options: ["Eşit", "2 katı", "4 katı", "1/4 katı"], correctAnswer: 2, explanation: "Güç sabit kalır: gerilim 4 kat düşerse akım 4 kat artar.", category: "Gemi Elektrik" },
    { id: 66, question: "Asenkron motorda kayma (slip) nedir?", options: ["Gerilim farkı", "Rotor ile stator arasındaki mesafe", "Senkron devir ile rotor devri arasındaki göreli fark", "Frekans farkı"], correctAnswer: 2, explanation: "s = (Ns − N)/Ns; kayma olmadan rotorda gerilim indüklenmez, dolayısıyla moment üretilemez.", category: "Gemi Elektrik" },
    { id: 67, question: "Senkron devri 1,500 dev/dak ve rotor devri 1,455 dev/dak olan motorun kayması yüzde kaçtır?", options: ["%5", "%1", "%2", "%3"], correctAnswer: 3, explanation: "s = (1,500 − 1,455)/1,500 = 45/1,500 = 0.03 → %3.", category: "Gemi Elektrik" },
    { id: 68, question: "50 Hz'de 4 kutuplu asenkron motorun senkron devri kaçtır?", options: ["1,500 dev/dak", "3,000 dev/dak", "750 dev/dak", "1,000 dev/dak"], correctAnswer: 0, explanation: "Ns = 120·f/p = 120 · 50/4 = 1,500 dev/dak.", category: "Gemi Elektrik" },
    { id: 69, question: "Frekans dönüştürücü (VFD) ile motor devri nasıl değiştirilir?", options: ["Kutup sayısını değiştirerek", "Gerilimi değiştirerek", "Frekansı değiştirerek", "Direnci değiştirerek"], correctAnswer: 2, explanation: "Devir frekansla doğru orantılıdır; momentin korunması için V/f oranı sabit tutulur.", category: "Gemi Elektrik" },
    { id: 70, question: "VFD kullanımının pompa ve fanlarda enerji tasarrufu sağlamasının nedeni nedir?", options: ["Gerilimin düşmesi", "Akımın sabit kalması", "Verimin artması", "Gücün devrin küpüyle orantılı olması"], correctAnswer: 3, explanation: "Devri %20 azaltmak gücü yaklaşık yarıya indirir; vana kısarak debi kontrolünde bu kazanç elde edilemez.", category: "Gemi Elektrik" },
    { id: 71, question: "Gemi elektrik sisteminin topraksız (IT) olarak tasarlanmasının temel gerekçesi nedir?", options: ["Maliyet", "Tek noktada toprak kaçağı oluştuğunda sistemin çalışmaya devam edebilmesi", "Verim", "Basitlik"], correctAnswer: 1, explanation: "Kritik tüketiciler ilk kaçakta durmaz; ancak ikinci bir kaçak kısa devre yaratacağından arıza derhal aranır.", category: "Gemi Elektrik" },
    { id: 72, question: "Yalıtım izleme cihazının alarm vermesi hâlinde ne yapılır?", options: ["Gerilim artırılır", "Yük atılır", "Cihaz kapatılır", "Devreler sırayla ayrılarak kaçağın hangi kolda olduğu bulunur"], correctAnswer: 3, explanation: "Kaçak bulunmazsa ikinci bir arıza kısa devre ve yangına yol açabilir; arama sistematik yapılır.", category: "Gemi Elektrik" },
    { id: 73, question: "Megger ölçümünde motor sargı yalıtım direnci için genel kabul gören asgari değer nedir?", options: ["100 MΩ", "0.1 MΩ", "1 MΩ", "10 MΩ"], correctAnswer: 2, explanation: "Pratik kural: her kV çalışma gerilimi için 1 MΩ, en az 1 MΩ; düşük değerde motor kurutulur.", category: "Gemi Elektrik" },
    { id: 74, question: "Yalıtım direnci ölçümü öncesi hangi işlem zorunludur?", options: ["Yağ eklemek", "Devri ölçmek", "Motoru ısıtmak", "Devreyi enerjiden ayırmak ve kapasitif yükü boşaltmak"], correctAnswer: 3, explanation: "Enerjili devrede ölçüm hem cihazı bozar hem ölümcül tehlike yaratır; ölçüm sonrası deşarj da yapılır.", category: "Gemi Elektrik" },
    { id: 75, question: "Aşırı akım rölesinin (overcurrent relay) işlevi nedir?", options: ["Akım sınırı aşıldığında devreyi açarak kablo ve ekipmanı korumak", "Frekansı ayarlamak", "Güç faktörünü düzeltmek", "Gerilimi ayarlamak"], correctAnswer: 0, explanation: "Ters zamanlı karakteristikte, akım büyüdükçe açma süresi kısalır; seçicilik için kademeli ayarlanır.", category: "Gemi Elektrik" },
    { id: 76, question: "Koruma sisteminde 'seçicilik' (discrimination) neyi ifade eder?", options: ["Tüm devrelerin açmasını", "Hiçbir devrenin açmamasını", "En hızlı açmayı", "Yalnızca arızaya en yakın koruma elemanının açmasını"], correctAnswer: 3, explanation: "Böylece arıza yalıtılırken sağlam devreler beslenmeye devam eder; ana şalter gereksiz yere açmaz.", category: "Gemi Elektrik" },
    { id: 77, question: "Ters güç rölesi (reverse power relay) neyi korur?", options: ["Kabloyu", "Motoru", "Paralel çalışan jeneratörün motor gibi çalışmasını engelleyerek dizel makineyi", "Trafoyu"], correctAnswer: 2, explanation: "Yakıt kesilirse jeneratör şebekeden güç çekerek motor gibi döner; bu, dizel makineye zarar verir.", category: "Gemi Elektrik" },
    { id: 78, question: "Düşük gerilim rölesi (under-voltage relay) hangi işlevi görür?", options: ["Gerilim düştüğünde şalterin açmasını sağlayarak motorların zarar görmesini önler", "Frekansı ayarlar", "Faz sırasını kontrol eder", "Aşırı yükü korur"], correctAnswer: 0, explanation: "Düşük gerilimde motorlar aşırı akım çeker ve ısınır; ayrıca gerilim dönüşünde kontrolsüz yeniden kalkışı engeller.", category: "Gemi Elektrik" },
    { id: 79, question: "Faz sırası (phase sequence) kontrolü neden gereklidir?", options: ["Frekans için", "Akım için", "Gerilim için", "Motorun ters yönde dönmesini önlemek için"], correctAnswer: 3, explanation: "Yanlış faz sırası pompa ve fanları ters döndürür; kıyı bağlantısı ve jeneratör paralellemesinde de kontrol edilir.", category: "Gemi Elektrik" },
    { id: 80, question: "Senkronoskop ibresinin yavaşça saat yönünde dönmesi neyi gösterir?", options: ["Gerilim farkını", "Faz sırası hatasını", "Gelen jeneratörün frekansının şebekeden düşük olduğunu", "Gelen jeneratörün frekansının şebekeden biraz yüksek olduğunu"], correctAnswer: 3, explanation: "Yavaş saat yönü dönüş istenen durumdur; ibre 12 konumuna gelirken şalter kapatılır.", category: "Gemi Elektrik" },
    { id: 81, question: "Senkronizasyonda faz farkı büyükken şalterin kapatılması ne yaratır?", options: ["Gerilim artışı", "Yumuşak devreye girme", "Büyük akım darbesi ve mekanik zorlanma", "Frekans artışı"], correctAnswer: 2, explanation: "Şok akımı sargıları ve kaplini zorlar; bu yüzden otomatik senkronizasyon cihazları kullanılır.", category: "Gemi Elektrik" },
    { id: 82, question: "AVR (otomatik gerilim regülatörü) neyi kontrol eder?", options: ["Devri", "Frekansı", "Yakıt debisini", "Uyartım akımını ayarlayarak çıkış gerilimini"], correctAnswer: 3, explanation: "Yük değiştikçe uyartım ayarlanır; böylece gerilim sabit kalır ve paralelde reaktif güç paylaşımı sağlanır.", category: "Gemi Elektrik" },
    { id: 83, question: "Acil switchboard'un ana switchboard'dan ayrı olmasının nedeni nedir?", options: ["Maliyet", "Ana pano devre dışı kalsa dahi acil tüketicilerin beslenebilmesi", "Bakım kolaylığı", "Yer darlığı"], correctAnswer: 1, explanation: "Acil pano fribord güvertesi üstünde ve makine dairesi dışında bulunur; acil jeneratörden beslenir.", category: "Gemi Elektrik" },
    { id: 84, question: "Acil aküler (batteries) hangi tüketicileri besler?", options: ["Acil aydınlatma, GMDSS ve alarm gibi kritik yükleri geçici süreyle", "Ana makineyi", "Vinçleri", "Tüm gemiyi"], correctAnswer: 0, explanation: "Acil jeneratör devreye girene kadar ve arızasında kesintisiz besleme sağlar; kapasite ve şarj durumu düzenli kontrol edilir.", category: "Gemi Elektrik" },
    { id: 85, question: "Akü odasında havalandırmanın zorunlu olmasının nedeni nedir?", options: ["Nem", "Koku", "Isı", "Şarj sırasında açığa çıkan hidrojenin patlayıcı karışım oluşturması"], correctAnswer: 3, explanation: "Hidrojen hafif olduğu için tavanda birikir; kıvılcım kaynakları yasaktır ve havalandırma sürekli çalışır.", category: "Gemi Elektrik" },
    { id: 86, question: "Kurşun-asit akülerde elektrolit yoğunluğu neyi gösterir?", options: ["İç direnci", "Sıcaklığı", "Şarj durumunu", "Kapasiteyi"], correctAnswer: 2, explanation: "Tam şarjda yaklaşık 1.28 g/cm³, deşarjda 1.15'e düşer; ölçüm hidrometre ile yapılır.", category: "Gemi Elektrik" },
    { id: 87, question: "200 Ah kapasiteli bir akü 10 A ile deşarj edilirse teorik olarak kaç saat dayanır?", options: ["40 saat", "100 saat", "10 saat", "20 saat"], correctAnswer: 3, explanation: "t = 200/10 = 20 saat; gerçekte deşarj hızı arttıkça kullanılabilir kapasite düşer.", category: "Gemi Elektrik" },
    { id: 88, question: "Kablo kesitinin yetersiz seçilmesi ne yaratır?", options: ["Aşırı ısınma ve gerilim düşümü", "Düşük akım", "Yüksek güç faktörü", "Yüksek verim"], correctAnswer: 0, explanation: "Kesit; akım taşıma kapasitesi, gerilim düşümü ve kısa devre dayanımı birlikte değerlendirilerek seçilir.", category: "Gemi Elektrik" },
    { id: 89, question: "Uzun bir hatta gerilim düşümünü azaltmanın en doğrudan yolu nedir?", options: ["Akımı artırmak", "Gerilimi düşürmek", "Frekansı artırmak", "Kablo kesitini büyütmek"], correctAnswer: 3, explanation: "ΔV = I·R; kesit büyüdükçe direnç ve dolayısıyla gerilim düşümü azalır.", category: "Gemi Elektrik" },
    { id: 90, question: "Gemide kıyı bağlantısı (shore connection) kullanılmadan önce ne kontrol edilir?", options: ["Yalnızca kablo boyu", "Yalnızca gerilim", "Gerilim, frekans, faz sırası ve topraklama", "Yalnızca akım"], correctAnswer: 2, explanation: "Yanlış faz sırası motorları ters döndürür; uyumsuz gerilim/frekans ekipmanı tahrip eder.", category: "Gemi Elektrik" },
    { id: 91, question: "Yüksek gerilimli (HV) sistemlerde çalışmadan önce yapılması gereken zorunlu işlem nedir?", options: ["Yalnızca eldiven giymek", "Yalnızca şalteri açmak", "Enerjiyi kesmek, kilitlemek, gerilimsizliği doğrulamak ve topraklamak", "Yalnızca etiketlemek"], correctAnswer: 2, explanation: "HV'de kapasitif yük ve geri besleme riski vardır; topraklama seti takılmadan çalışmaya başlanmaz.", category: "Gemi Elektrik" },
    { id: 92, question: "Elektrik panosunda ark flaşı (arc flash) riskine karşı temel önlem nedir?", options: ["Eldiven takmamak", "Kapağı açık bırakmak", "Hızlı çalışmak", "Uygun ark dayanımlı KKD ve enerjisiz çalışma"], correctAnswer: 3, explanation: "Ark flaşı çok yüksek sıcaklık ve basınç dalgası üretir; mümkün olan her durumda enerjisiz çalışılır.", category: "Gemi Elektrik" },
    { id: 93, question: "Elektrik yangınında ilk yapılması gereken nedir?", options: ["Enerjiyi kesmek", "Kapıyı açmak", "Fanı çalıştırmak", "Su sıkmak"], correctAnswer: 0, explanation: "Enerji kesildikten sonra yangın sınıfı değişir; CO₂ veya uygun temiz gaz kullanılır, su asla kullanılmaz.", category: "Gemi Elektrik" },
    { id: 94, question: "Motor koruma rölesinde termik ayarın motor anma akımına göre yapılmasının nedeni nedir?", options: ["Güç faktörü için", "Verim için", "Aşırı yüklenmede sargının ısınmadan korunması için", "Devir için"], correctAnswer: 2, explanation: "Çok yüksek ayar motoru yakar, çok düşük ayar gereksiz açmalara yol açar.", category: "Gemi Elektrik" },
    { id: 95, question: "Motorun tek fazda kalması (single phasing) neye yol açar?", options: ["Gerilimin artmasına", "Momentin artmasına", "Devrin artmasına", "Kalan fazlarda aşırı akım ve hızlı ısınmaya"], correctAnswer: 3, explanation: "Sigorta atması veya kontak arızası tipik nedendir; faz kaybı rölesi bu duruma karşı koruma sağlar.", category: "Gemi Elektrik" },
    { id: 96, question: "Motorun yol alma akımı anma akımının yaklaşık kaç katıdır (doğrudan yol vermede)?", options: ["2–3 katı", "5–7 katı", "15–20 katı", "1–2 katı"], correctAnswer: 1, explanation: "Yüksek kalkış akımı şebekede gerilim çökmesine yol açabilir; büyük motorlarda yumuşak yol verici kullanılır.", category: "Gemi Elektrik" },
    { id: 97, question: "Yumuşak yol vericinin (soft starter) VFD'ye göre farkı nedir?", options: ["Daha pahalıdır", "Moment üretmez", "Devri sürekli ayarlar", "Yalnızca kalkış akımını sınırlar, çalışma devrini değiştirmez"], correctAnswer: 3, explanation: "Soft starter gerilimi kademeli yükseltir; sürekli hız kontrolü gerekiyorsa VFD kullanılır.", category: "Gemi Elektrik" },
    { id: 98, question: "Harmonik bozulmanın (THD) gemi şebekesindeki temel kaynağı nedir?", options: ["Motorlar", "Aydınlatma", "Frekans dönüştürücüler ve doğrultucular gibi doğrusal olmayan yükler", "Isıtıcılar"], correctAnswer: 2, explanation: "Harmonikler trafo ve jeneratörde ek ısınma, ölçüm hatası ve koruma yanlış açmalarına yol açar.", category: "Gemi Elektrik" },
    { id: 99, question: "Harmoniklerin azaltılmasında hangi yöntem kullanılır?", options: ["Gerilim yükseltmek", "Frekans düşürmek", "Kablo kısaltmak", "Filtre kullanmak ve çok darbeli (12-pulse) doğrultucu tercih etmek"], correctAnswer: 3, explanation: "Pasif/aktif filtreler ve faz kaydırmalı trafolu doğrultucular harmonik içeriğini belirgin biçimde düşürür.", category: "Gemi Elektrik" },
    { id: 100, question: "Gemide UPS'in (kesintisiz güç kaynağı) tipik kullanım amacı nedir?", options: ["Seyir ve otomasyon sistemlerini kesintisiz beslemek", "Vinçleri beslemek", "Isıtıcıları beslemek", "Ana makineyi beslemek"], correctAnswer: 0, explanation: "ECDIS, GMDSS ve otomasyon panoları güç kesintisinde dahi çalışmalıdır; UPS bataryası düzenli test edilir.", category: "Gemi Elektrik" },
    { id: 101, question: "Bir jeneratörün 800 kW yükte cosφ 0.8 ile çalıştığı biliniyorsa çektiği görünür güç kaç kVA'dır?", options: ["1,250 kVA", "640 kVA", "800 kVA", "1,000 kVA"], correctAnswer: 3, explanation: "S = P/cosφ = 800/0.8 = 1,000 kVA.", category: "Gemi Elektrik" },
    { id: 102, question: "Nominal gücü 1,000 kVA olan jeneratör 1,000 kW aktif güç verebilir mi?", options: ["Hayır, hiçbir koşulda", "Evet, her zaman", "Hayır; ancak cosφ = 1 olsaydı mümkün olurdu", "Evet, cosφ 0.8'de"], correctAnswer: 2, explanation: "Anma değeri kVA cinsindendir; aktif güç kapasitesi cosφ ile sınırlanır (0.8'de 800 kW).", category: "Gemi Elektrik" },
    { id: 103, question: "Üç fazlı dengeli yükte nötr akımı ne olur?", options: ["Teorik olarak sıfırdır", "√3 katıdır", "3 katıdır", "Faz akımına eşittir"], correctAnswer: 0, explanation: "Dengeli yükte üç fazın vektörel toplamı sıfırdır; dengesizlik arttıkça nötrden akım geçer.", category: "Gemi Elektrik" },
    { id: 104, question: "Faz dengesizliğinin motorlar üzerindeki etkisi nedir?", options: ["Devir artar", "Akım düşer", "Verim artar", "Ters bileşen akımı nedeniyle ek ısınma ve moment dalgalanması"], correctAnswer: 3, explanation: "Küçük bir gerilim dengesizliği bile akımda büyük dengesizlik yaratır; sargı sıcaklığı hızla yükselir.", category: "Gemi Elektrik" },
    { id: 105, question: "Bir elektrik motorunun verimi %90 ve şaft gücü 45 kW ise şebekeden çekilen güç kaç kW'dır?", options: ["54.0 kW", "40.5 kW", "45.0 kW", "50.0 kW"], correctAnswer: 3, explanation: "Pgiriş = 45/0.90 = 50 kW; aradaki 5 kW kayıp ısıya dönüşür.", category: "Gemi Elektrik" },
    { id: 106, question: "Elektrik motorlarının IP koruma sınıfında ilk rakam neyi belirtir?", options: ["Sıcaklığa karşı korumayı", "Suya karşı korumayı", "Katı cisim ve toza karşı korumayı", "Darbeye karşı korumayı"], correctAnswer: 2, explanation: "İlk rakam katı cisim/toz, ikinci rakam su korumasıdır; güverte ekipmanında IP56 ve üzeri tercih edilir.", category: "Gemi Elektrik" },
    { id: 107, question: "Ex (patlamaya karşı korumalı) ekipman nerede zorunludur?", options: ["Köprüüstünde", "Kamaralarda", "Makine dairesinde", "Tehlikeli bölgelerde (tanker güvertesi, pompa dairesi, boya dolabı)"], correctAnswer: 3, explanation: "Bu bölgelerde yanıcı gaz bulunabilir; sertifikalı Ex ekipmanın gövde bütünlüğü bozulmadan kullanılması şarttır.", category: "Gemi Elektrik" },
    { id: 108, question: "Ex ekipmanın kapağının eksik cıvatayla kapatılması neden kabul edilemez?", options: ["Estetik nedeniyle", "Alev geçirmez boşluk bütünlüğünün bozulması nedeniyle", "Ağırlık nedeniyle", "Isı nedeniyle"], correctAnswer: 1, explanation: "Ex d koruması, iç patlamanın dışarı yayılmasını engelleyen dar boşluklara dayanır; eksik cıvata bu korumayı ortadan kaldırır.", category: "Gemi Elektrik" },
    { id: 109, question: "Kablo rakorlarının (gland) doğru sıkılmasının işlevi nedir?", options: ["Mekanik tutuş, sızdırmazlık ve gerekli hâllerde ekranlama sürekliliği", "Isı iletimi", "Akım taşıma", "Estetik"], correctAnswer: 0, explanation: "Gevşek rakor nem girişine ve zırh sürekliliğinin kopmasına yol açar; Ex kurulumlarda ayrıca sertifikalı tip gerekir.", category: "Gemi Elektrik" },
    { id: 110, question: "Aydınlatma devrelerinde acil aydınlatmanın ayrı beslenmesinin nedeni nedir?", options: ["Verim", "Estetik", "Maliyet", "Ana güç kesildiğinde kaçış yollarının aydınlık kalması"], correctAnswer: 3, explanation: "Acil aydınlatma acil panodan veya bataryadan beslenir; düzenli test edilerek çalışırlığı doğrulanır.", category: "Gemi Elektrik" },
    { id: 111, question: "Bir devre kesicinin kesme kapasitesi (breaking capacity) neyi ifade eder?", options: ["Açma süresini", "Sürekli akımı", "Güvenle kesebileceği azami kısa devre akımını", "Nominal gerilimi"], correctAnswer: 2, explanation: "Kısa devre akımı bu değeri aşarsa kesici tahrip olur; hesaplanan prospektif akıma göre seçilir.", category: "Gemi Elektrik" },
    { id: 112, question: "Sigortanın devre kesiciye göre dezavantajı nedir?", options: ["Daha pahalı olması", "Seçici olmaması", "Daha yavaş olması", "Tek kullanımlık olması ve değiştirilmesi gerekmesi"], correctAnswer: 3, explanation: "Buna karşılık sigorta çok yüksek kısa devre akımlarını hızlı ve ucuz biçimde keser.", category: "Gemi Elektrik" },
    { id: 113, question: "Yanlış amperajda sigorta kullanılması neden tehlikelidir?", options: ["Devre korunmaz veya gereksiz açar; yangın riski doğar", "Gerilim düşer", "Frekans değişir", "Verim düşer"], correctAnswer: 0, explanation: "Büyük sigorta kabloyu korumaz; küçük sigorta ise kritik ekipmanı gereksiz durdurur. Asla köprüleme yapılmaz.", category: "Gemi Elektrik" },
    { id: 114, question: "Bara (busbar) sıkma torklarının kontrol edilmesi neden gereklidir?", options: ["Ağırlık", "Akım ölçümü", "Estetik", "Gevşek bağlantının ısınıp ark ve yangına yol açması nedeniyle"], correctAnswer: 3, explanation: "Gevşeklik yüksek temas direnci demektir; termografi ile ısınan bağlantılar erken tespit edilir.", category: "Gemi Elektrik" },
    { id: 115, question: "Elektrik motorunun sargı sıcaklığını izlemek için ne kullanılır?", options: ["Manometre", "Basınç sensörü", "PT100 veya termistör", "Akış ölçer"], correctAnswer: 2, explanation: "Gömülü sıcaklık sensörleri aşırı ısınmayı, koruma rölesinden daha doğrudan gösterir.", category: "Gemi Elektrik" },
    { id: 116, question: "PT100 sensörünün çalışma prensibi nedir?", options: ["Basınç ölçmesi", "Gerilim üretmesi", "Sıcaklıkla direncinin değişmesi", "Işık yayması"], correctAnswer: 2, explanation: "0 °C'de 100 Ω olan platin direnç sıcaklıkla doğrusala yakın artar; üç veya dört telli bağlantı kablo direncini telafi eder.", category: "Gemi Elektrik" },
    { id: 117, question: "Termokupl (thermocouple) neyi ölçer ve prensibi nedir?", options: ["Debi, türbin etkisi", "Seviye, kapasitans", "Basınç, piezo etkisi", "Sıcaklık, iki farklı metal birleşiminde oluşan termoelektrik gerilim"], correctAnswer: 3, explanation: "Seebeck etkisiyle sıcaklık farkı gerilim üretir; yüksek sıcaklıklarda (egzoz) yaygın kullanılır.", category: "Gemi Elektrik" },
    { id: 118, question: "Elektrik pano önünde yalıtkan paspas bulundurulmasının amacı nedir?", options: ["Toprakla temas yolunu keserek çarpılma riskini azaltmak", "Isı yalıtımı", "Ses yalıtımı", "Temizlik"], correctAnswer: 0, explanation: "Yalıtkan paspas ve kuru zemin, HV panolarda zorunlu emniyet önlemlerindendir.", category: "Gemi Elektrik" },
    { id: 119, question: "Elektrik çarpmasında kurtarıcının ilk yapması gereken nedir?", options: ["Kazazedeyi çekmek", "Kazazedeye dokunmak", "Enerjiyi kesmek veya yalıtkan bir cisimle kazazedeyi ayırmak", "Su dökmek"], correctAnswer: 2, explanation: "Kurtarıcı da devrenin parçası olabilir; enerji kesilmeden temas edilmez.", category: "Gemi Elektrik" },
    { id: 120, question: "Elektrik bakım işlerinde 'permit to work' ile birlikte uygulanan LOTO neyi güvence altına alır?", options: ["Hızlı çalışmayı", "Malzeme temini", "Kayıt tutulmasını", "Devrenin başkası tarafından enerjilendirilememesini"], correctAnswer: 3, explanation: "Kilit anahtarı işi yapan kişide kalır; birden çok kişi çalışıyorsa çoklu kilit düzeneği kullanılır.", category: "Gemi Elektrik" },
    { id: 121, question: "Doğru akım (DC) sistemlerin gemide tipik kullanım alanı nedir?", options: ["Ana güç dağıtımı", "Acil aydınlatma, alarm, haberleşme ve kontrol devreleri", "Vinç motorları", "Pompa motorları"], correctAnswer: 1, explanation: "Batarya destekli 24 V DC devreler, güç kesintisinde çalışmaya devam eder.", category: "Gemi Elektrik" },
    { id: 122, question: "Redresörün (rectifier) işlevi nedir?", options: ["Gerilimi yükseltmek", "Frekansı değiştirmek", "DC'yi AC'ye çevirmek", "AC'yi DC'ye çevirmek"], correctAnswer: 3, explanation: "Batarya şarj devrelerinde ve VFD giriş katında kullanılır; çıkışta filtreleme ile dalgalanma azaltılır.", category: "Gemi Elektrik" },
    { id: 123, question: "İnvertörün işlevi nedir?", options: ["Akım sınırlamak", "AC'yi DC'ye çevirmek", "DC'yi AC'ye çevirmek", "Direnç ölçmek"], correctAnswer: 2, explanation: "UPS ve VFD çıkış katında kullanılır; PWM ile istenen frekans ve gerilim üretilir.", category: "Gemi Elektrik" },
    { id: 124, question: "Bir VFD'nin çıkışına doğrudan ölçü aleti bağlanmasının sakıncası nedir?", options: ["Akım yüksektir", "Gerilim düşüktür", "Ölçüm hızlıdır", "PWM dalga biçimi nedeniyle standart aletlerin hatalı okuması"], correctAnswer: 3, explanation: "True-RMS ve uygun bant genişliğine sahip aletler gerekir; aksi hâlde okunan değer gerçeği yansıtmaz.", category: "Gemi Elektrik" },
    { id: 125, question: "VFD beslenen motorlarda yatak akımı (bearing current) sorununa karşı ne kullanılır?", options: ["Yalıtımlı yatak veya şaft topraklama fırçası", "Daha kısa kablo", "Daha yüksek frekans", "Daha büyük motor"], correctAnswer: 0, explanation: "Yüksek frekanslı anahtarlama ortak mod gerilimi üretir; yatakta elektro-erozyon oluşabilir.", category: "Gemi Elektrik" },
    { id: 126, question: "Elektrikli tahrik (electric propulsion) sisteminin temel avantajı nedir?", options: ["Daha hafif olması", "Bakım gerektirmemesi", "Daha ucuz olması", "Jeneratörlerin yüke göre devreye alınabilmesi ve yerleşim esnekliği"], correctAnswer: 3, explanation: "Değişken yük profilinde (feribot, açık deniz gemileri) yakıt verimi ve manevra kabiliyeti artar.", category: "Gemi Elektrik" },
    { id: 127, question: "Azipod tipi tahrik sisteminin manevra açısından yararı nedir?", options: ["Daha az bakım", "Daha yüksek hız", "Pervanenin 360° dönebilmesiyle üstün manevra kabiliyeti", "Daha az güç"], correctAnswer: 2, explanation: "Ayrı dümen gerekmez; itki doğrudan istenen yöne verilir ve limanda römorkör ihtiyacı azalır.", category: "Gemi Elektrik" },
    { id: 128, question: "Batarya (enerji depolama) sistemlerinin gemide kullanımının temel yararı nedir?", options: ["Yük dalgalanmalarını karşılayıp jeneratörleri verimli bölgede tutmak", "Gürültü üretmek", "Bakım artırmak", "Ağırlık azaltmak"], correctAnswer: 0, explanation: "Peak shaving ve spinning reserve işlevleriyle yakıt tüketimi ve emisyon azalır.", category: "Gemi Elektrik" },
    { id: 129, question: "Lityum-iyon batarya sistemlerinde en kritik emniyet konusu nedir?", options: ["Gürültü", "Titreşim", "Ağırlık", "Termal kaçak (thermal runaway) riski ve yangın söndürme zorluğu"], correctAnswer: 3, explanation: "Hücre yönetim sistemi, sıcaklık izleme, ayrı yangın bölmesi ve havalandırma tasarımın parçasıdır.", category: "Gemi Elektrik" },
    { id: 130, question: "Elektrik sisteminde 'blackout' nasıl tanımlanır?", options: ["Gerilimin düşmesi", "Frekansın değişmesi", "Bir devrenin açması", "Tüm elektrik üretiminin kesilmesi"], correctAnswer: 3, explanation: "Blackout, ana makine ve dümen dahil tüm sistemlerin durması demektir; acil jeneratör devreye girerek kritik yükleri besler.", category: "Gemi Elektrik" },
    { id: 131, question: "Blackout'un en yaygın nedeni nedir?", options: ["Akü arızası", "Kablo kopması", "Jeneratörün aşırı yüklenmesi veya yakıt/soğutma kaynaklı durması", "Aydınlatma arızası"], correctAnswer: 2, explanation: "Yük yönetimi, yakıt filtresi bakımı ve otomatik yedek devreye alma bu riski azaltır.", category: "Gemi Elektrik" },
    { id: 132, question: "Blackout sonrası 'dead ship start' için hangi kaynak gerekir?", options: ["Şaft jeneratörü", "Kıyı bağlantısı", "Ana jeneratör", "Acil jeneratör veya bağımsız başlatma havası/akü kaynağı"], correctAnswer: 3, explanation: "SOLAS, dış yardım olmaksızın geminin makinelerini çalıştırabilme kabiliyetini şart koşar.", category: "Gemi Elektrik" },
    { id: 133, question: "Jeneratör koruma sisteminde diferansiyel rölenin işlevi nedir?", options: ["Aşırı yükü korumak", "Sargı içi kısa devre gibi bölge içi arızaları hızlı biçimde ayırmak", "Gerilimi ayarlamak", "Frekansı ayarlamak"], correctAnswer: 1, explanation: "Giriş ve çıkış akımları karşılaştırılır; fark oluşursa arıza koruma bölgesi içindedir ve anında açma yapılır.", category: "Gemi Elektrik" },
    { id: 134, question: "Ana switchboard'da ölçü aletlerinin (ampermetre, voltmetre, kWmetre) işlevi nedir?", options: ["Yük dağılımı ve sistem sağlığının sürekli izlenmesi", "Koruma sağlamak", "Frekans üretmek", "Süs"], correctAnswer: 0, explanation: "Anormal değerler arızanın erken göstergesidir; ölçümler vardiya kayıtlarına işlenir.", category: "Gemi Elektrik" },
    { id: 135, question: "Frekansın nominal değerin altına düşmesi hangi soruna yol açar?", options: ["Gerilimin artması", "Akımın azalması", "Motorların hızlanması", "Motorların yavaşlaması, soğutma fanlarının zayıflaması ve aşırı ısınma"], correctAnswer: 3, explanation: "Frekans düşüşü genellikle aşırı yükün göstergesidir; yük atma sistemi devreye girmelidir.", category: "Gemi Elektrik" },
    { id: 136, question: "Bir tüketicinin 'essential' (temel) olarak sınıflandırılması ne anlama gelir?", options: ["Yedeğinin olmaması", "Konfor amaçlı olması", "Geminin sevk, emniyet ve manevrası için gerekli olması", "Yalnızca limanda kullanılması"], correctAnswer: 2, explanation: "Dümen, yağ pompaları, soğutma pompaları ve seyir donanımı bu gruptadır; yük atmada en son etkilenirler.", category: "Gemi Elektrik" },
    { id: 137, question: "Elektrik dağıtımında yedekli besleme (dual feed) neden kullanılır?", options: ["Verim", "Basitlik", "Maliyet", "Kritik tüketicinin bir kaynak kaybında diğerinden beslenebilmesi"], correctAnswer: 3, explanation: "Otomatik transfer şalteri ile besleme kesintisiz devam eder; test edilmesi kritik öneme sahiptir.", category: "Gemi Elektrik" },
    { id: 138, question: "Kablo güzergâhlarının yangın bölmelerinden geçişinde ne yapılır?", options: ["Onaylı yangın durdurucu (fire stop) dolgu uygulanır", "Kablo kesilir", "Kablo boyanır", "Boşluk bırakılır"], correctAnswer: 0, explanation: "Aksi hâlde A sınıfı bölmenin bütünlüğü bozulur ve yangın komşu mahalle geçer.", category: "Gemi Elektrik" },
    { id: 139, question: "Yangına dayanıklı (fire-resistant) kablo hangi devrelerde kullanılır?", options: ["Isıtıcılarda", "Kamaralarda", "Aydınlatmada", "Acil devreler ve yangın sırasında çalışması gereken sistemlerde"], correctAnswer: 3, explanation: "Yangın pompası, acil aydınlatma ve alarm devreleri belirli süre işlevini sürdürmelidir.", category: "Gemi Elektrik" },
    { id: 140, question: "Elektrik ekipmanının düzenli temizliğinin arıza önlemedeki rolü nedir?", options: ["Gürültü azaltma", "Estetik", "Toz ve tuz birikiminin yalıtımı düşürmesini ve soğutmayı bozmasını engellemek", "Ağırlık azaltma"], correctAnswer: 2, explanation: "İletken toz yüzey kaçağı yaratır; motor soğutma kanatlarındaki kir ise sıcaklığı yükseltir.", category: "Gemi Elektrik" },
    { id: 141, question: "Bir jeneratörün 'kW' ve 'kVA' değerlerinin farklı olmasının nedeni nedir?", options: ["Gerilim farkı", "Ölçüm hatası", "Yükün reaktif bileşen içermesi (cosφ < 1)", "Frekans farkı"], correctAnswer: 2, explanation: "Reaktif güç iş üretmez ama akım taşır; bu yüzden jeneratör kapasitesi kVA ile tanımlanır.", category: "Gemi Elektrik" },
    { id: 142, question: "Bir motorun anma akımı 60 A ve koruma rölesi %115'e ayarlıysa açma akımı yaklaşık kaç A'dir?", options: ["72 A", "78 A", "63 A", "69 A"], correctAnswer: 3, explanation: "60 × 1.15 = 69 A; bu değerin üzerinde ters zamanlı karakteristikle açma gerçekleşir.", category: "Gemi Elektrik" },
    { id: 143, question: "Elektrik motorunun çalışma sıcaklığının yalıtım sınıfını aşması ne yaratır?", options: ["Yalıtım ömrünün hızla kısalması", "Devir artışı", "Akım azalması", "Verim artışı"], correctAnswer: 0, explanation: "Genel kural: her 10 °C aşım yalıtım ömrünü yaklaşık yarıya indirir.", category: "Gemi Elektrik" },
    { id: 144, question: "Yalıtım sınıfı F olan bir motorun izin verilen sıcaklık sınırı yaklaşık kaç °C'dir?", options: ["105 °C", "130 °C", "155 °C", "180 °C"], correctAnswer: 2, explanation: "Sınıf B 130 °C, F 155 °C, H 180 °C sınırına sahiptir; genellikle F yalıtım B sıcaklık artışıyla kullanılır.", category: "Gemi Elektrik" },
    { id: 145, question: "Gemi elektrik sisteminde topraklama ile 'gövdeye bağlama' arasındaki fark nedir?", options: ["Topraklama gerekmez", "Gövdeye bağlama yasaktır", "Aynıdır", "Topraklama nötr referansı, gövdeye bağlama ise ekipman güvenliği içindir"], correctAnswer: 3, explanation: "IT sistemde nötr topraklanmaz; buna karşılık tüm metal gövdeler eşpotansiyel olacak şekilde bağlanır.", category: "Gemi Elektrik" },
    { id: 146, question: "Elektrikli el aletlerinde gemide düşük gerilim (örneğin 24 V) tercih edilmesinin nedeni nedir?", options: ["Güç fazlalığı", "Islak ve iletken ortamda çarpılma riskinin azaltılması", "Kablo tasarrufu", "Verim artışı"], correctAnswer: 1, explanation: "Ayrıca yalıtım trafosu veya çift izolasyonlu aletler kullanılır; kaçak akım koruması da uygulanır.", category: "Gemi Elektrik" },
    { id: 147, question: "Yalıtım trafosunun (isolation transformer) sağladığı koruma nedir?", options: ["Frekans değiştirme", "Akım sınırlama", "Gerilim yükseltme", "Besleme ile tüketici arasındaki galvanik ayrım sayesinde toprak üzerinden devre tamamlanmaması"], correctAnswer: 3, explanation: "Tek noktaya temas hâlinde akım yolu oluşmaz; özellikle taşınabilir aletlerde etkili bir önlemdir.", category: "Gemi Elektrik" },
    { id: 148, question: "Elektrik arıza aramasında ilk adım ne olmalıdır?", options: ["Sigortayı köprülemek", "Parça değiştirmek", "Belirtiyi tanımlayıp devre şeması üzerinde sistematik daraltma yapmak", "Gerilim yükseltmek"], correctAnswer: 2, explanation: "Rastgele parça değişimi hem maliyetli hem yanıltıcıdır; ölçümle doğrulanan sistematik yaklaşım esastır.", category: "Gemi Elektrik" },
    { id: 149, question: "Elektrik bakım kayıtlarında megger değerlerinin eğilim olarak izlenmesi neden önemlidir?", options: ["Maliyet için", "Stok için", "Denetim için", "Yalıtımdaki yavaş bozulmanın arıza oluşmadan görülebilmesi için"], correctAnswer: 3, explanation: "Tek bir ölçüm bağlam vermez; zaman içinde düşen eğilim bakım kararını tetikler.", category: "Gemi Elektrik" },
    { id: 150, question: "Elektrik işlerinde en yaygın ölümcül hata hangisidir?", options: ["Enerjinin kesildiğini doğrulamadan çalışmaya başlamak", "Yanlış kablo rengi", "Yanlış ölçüm birimi", "Yanlış alet kullanımı"], correctAnswer: 0, explanation: "Test cihazı çalışır bilinen bir kaynakta doğrulanmalı, ölçüm yapılmalı ve ardından yeniden doğrulanmalıdır.", category: "Gemi Elektrik" },
  ],
  automation: [
    { id: 51, question: "Kapalı çevrim (closed loop) kontrolün açık çevrimden farkı nedir?", options: ["Daha ucuz olması", "Sensör gerektirmemesi", "Daha hızlı olması", "Çıkışın ölçülüp geri besleme ile hataya göre düzeltme yapılması"], correctAnswer: 3, explanation: "Geri besleme, bozucu etkilere ve model hatalarına rağmen set değerine yakınsamayı sağlar.", category: "Otomasyon" },
    { id: 52, question: "PID kontrolörde oransal (P) terim ne yapar?", options: ["Set değerini değiştirir", "Hatanın integralini alır", "Anlık hatayla orantılı düzeltme üretir", "Hatanın türevini alır"], correctAnswer: 2, explanation: "P kazancı arttıkça tepki hızlanır ancak kalıcı hata tamamen giderilmez ve salınım eğilimi artar.", category: "Otomasyon" },
    { id: 53, question: "PID kontrolörde integral (I) terimin temel katkısı nedir?", options: ["Kalıcı durum hatasını (offset) sıfırlamak", "Tepkiyi yavaşlatmak", "Set değerini artırmak", "Gürültüyü azaltmak"], correctAnswer: 0, explanation: "Zamanla biriken hata düzeltilir; ancak aşırı integral aşma (overshoot) ve integral windup yaratır.", category: "Otomasyon" },
    { id: 54, question: "PID kontrolörde türev (D) terimin işlevi nedir?", options: ["Set değerini değiştirmek", "Gürültüyü artırmak", "Kalıcı hatayı gidermek", "Hatanın değişim hızına tepki vererek aşmayı ve salınımı azaltmak"], correctAnswer: 3, explanation: "Öngörücü etki sağlar; buna karşılık ölçüm gürültüsünü büyüttüğü için gürültülü sinyallerde dikkatli kullanılır.", category: "Otomasyon" },
    { id: 55, question: "'Integral windup' sorunu nasıl oluşur?", options: ["Sensör arızasından", "Set değerinden", "Türev teriminden", "Aktüatör doyuma girerken integral teriminin birikmeye devam etmesiyle"], correctAnswer: 3, explanation: "Valf tam açıkken hata sürerse integral şişer ve set değerine ulaşıldığında büyük aşma oluşur; anti-windup ile sınırlanır.", category: "Otomasyon" },
    { id: 56, question: "Oransal bant (proportional band) %20 ise kazanç kaçtır?", options: ["0.2", "2", "5", "20"], correctAnswer: 2, explanation: "Kp = 100/PB = 100/20 = 5.", category: "Otomasyon" },
    { id: 57, question: "Kazancın çok yüksek seçilmesi kontrol döngüsünde neye yol açar?", options: ["Kalıcı hata", "Ölü bant", "Yavaş tepki", "Salınım ve kararsızlık"], correctAnswer: 3, explanation: "Sistem her düzeltmede hedefi aşar; kazanç, kararlılık ve hız arasında dengelenmelidir.", category: "Otomasyon" },
    { id: 58, question: "Kontrol vanasında 'ölü bant' (dead band) neyi ifade eder?", options: ["Vananın tam açık olduğu bölgeyi", "Giriş sinyali değiştiği hâlde çıkışın tepki vermediği aralığı", "Maksimum debiyi", "Minimum basıncı"], correctAnswer: 1, explanation: "Mekanik boşluk ve sürtünme kaynaklıdır; kontrol kalitesini düşürür ve döngüde limit çevrim yaratabilir.", category: "Otomasyon" },
    { id: 59, question: "Ölçüm sinyali standardı olarak 4–20 mA'nın tercih edilme nedeni nedir?", options: ["Sıfır değerin 4 mA olması sayesinde kablo kopmasının ayırt edilebilmesi", "Daha hızlı olması", "Daha az güç çekmesi", "Daha ucuz olması"], correctAnswer: 0, explanation: "0 mA okuması arıza demektir; ayrıca akım sinyali gerilim düşümünden ve gürültüden az etkilenir.", category: "Otomasyon" },
    { id: 60, question: "0–10 bar ölçen bir transmitter 12 mA gösteriyorsa basınç kaç bardır?", options: ["6 bar", "7.5 bar", "4 bar", "5 bar"], correctAnswer: 3, explanation: "Ölçek: (12 − 4)/(20 − 4) = 0.5 → 0.5 × 10 = 5 bar.", category: "Otomasyon" },
    { id: 61, question: "0–150 °C ölçen bir transmitter 16 mA veriyorsa sıcaklık kaç °C'dir?", options: ["75 °C", "90 °C", "112.5 °C", "120 °C"], correctAnswer: 2, explanation: "(16 − 4)/16 = 0.75 → 0.75 × 150 = 112.5 °C.", category: "Otomasyon" },
    { id: 62, question: "Bir seviye transmitteri 0–4 m aralığında ölçüyor ve 8 mA veriyorsa seviye kaç m'dir?", options: ["1.5 m", "2.0 m", "0.5 m", "1.0 m"], correctAnswer: 3, explanation: "(8 − 4)/16 = 0.25 → 0.25 × 4 = 1.0 m.", category: "Otomasyon" },
    { id: 63, question: "Diferansiyel basınç (DP) transmitteri ile seviye ölçümünde hangi büyüklük gereklidir?", options: ["Sıvının yoğunluğu", "Viskozite", "Debi", "Sıcaklık"], correctAnswer: 0, explanation: "h = ΔP/(ρ·g); yoğunluk değişirse ölçüm hatalı olur, bu yüzden yakıt tanklarında sıcaklık düzeltmesi de gerekebilir.", category: "Otomasyon" },
    { id: 64, question: "Yoğunluğu 1,000 kg/m³ olan sıvıda 0.4 bar diferansiyel basınç kaç m seviyeye karşılık gelir?", options: ["5.2 m", "2.0 m", "3.0 m", "4.1 m"], correctAnswer: 3, explanation: "h = ΔP/(ρ·g) = 40,000/(1,000 · 9.81) ≈ 4.08 m.", category: "Otomasyon" },
    { id: 65, question: "Orifis plakalı debi ölçümünde debi ile diferansiyel basınç arasındaki ilişki nedir?", options: ["İlişkisiz", "Doğru orantılı", "Debi, diferansiyel basıncın kareköküyle orantılı", "Ters orantılı"], correctAnswer: 2, explanation: "Q ∝ √ΔP; bu yüzden düşük debilerde ölçüm hassasiyeti belirgin biçimde düşer.", category: "Otomasyon" },
    { id: 66, question: "Elektromanyetik debimetre hangi akışkanlarda kullanılamaz?", options: ["Tatlı su", "Deniz suyu", "İletken olmayan akışkanlar (yakıt, yağ)", "Balast suyu"], correctAnswer: 2, explanation: "Faraday yasasına dayanır ve akışkanın iletken olmasını gerektirir; hidrokarbonlarda coriolis veya türbin tipi kullanılır.", category: "Otomasyon" },
    { id: 67, question: "Coriolis debimetrenin temel üstünlüğü nedir?", options: ["Basit olması", "Küçük olması", "Ucuz olması", "Doğrudan kütlesel debi ve yoğunluk ölçebilmesi"], correctAnswer: 3, explanation: "Bunker ölçümünde hacim-sıcaklık düzeltmesi gerekmediği için uyuşmazlıkları azaltır.", category: "Otomasyon" },
    { id: 68, question: "Bir kontrol vanasında 'fail-safe' konumu neden belirlenir?", options: ["Hava veya sinyal kaybında vananın emniyetli konuma gitmesi için", "Debi için", "Basınç için", "Enerji tasarrufu için"], correctAnswer: 0, explanation: "Örneğin yakıt vanası hava kaybında kapanır (fail close), soğutma vanası ise açılır (fail open).", category: "Otomasyon" },
    { id: 69, question: "Pnömatik aktüatörlü vanada 'positioner' ne sağlar?", options: ["Sıcaklık ölçümü", "Basınç ölçümü", "Vana konumunun geri besleme ile istenen değere tam oturmasını", "Debi ölçümü"], correctAnswer: 2, explanation: "Sürtünme ve yay karakteristiğinden doğan konum hatasını giderir; kontrol kalitesini belirgin biçimde artırır.", category: "Otomasyon" },
    { id: 70, question: "Kontrol vanasının karakteristiğinin 'eşit yüzdeli' (equal percentage) seçilmesi neyi hedefler?", options: ["Hızlı kapanma", "Düşük maliyet", "Doğrusal debi", "Sistem direnci değişse dahi kontrolün doğrusala yakın kalmasını"], correctAnswer: 3, explanation: "Boru direncinin baskın olduğu sistemlerde toplam karakteristik doğrusala yaklaşır ve kontrol kararlı olur.", category: "Otomasyon" },
    { id: 71, question: "Kaskad (cascade) kontrolde iç döngünün işlevi nedir?", options: ["Set değerini üretmek", "Bozucu etkileri hızlıca bastırarak dış döngünün işini kolaylaştırmak", "Alarm üretmek", "Veri kaydetmek"], correctAnswer: 1, explanation: "Örneğin sıcaklık (dış) döngüsü, buhar debisi (iç) döngüsüne set değeri verir; hızlı iç döngü bozucuları erken karşılar.", category: "Otomasyon" },
    { id: 72, question: "İleri besleme (feedforward) kontrolün avantajı nedir?", options: ["Daha ucuz olması", "Kararlılığı garanti etmesi", "Sensör gerektirmemesi", "Bozucu etkinin sonucu görülmeden önce düzeltme yapılması"], correctAnswer: 3, explanation: "Ölçülebilen bozucu (örneğin yük değişimi) doğrudan hesaba katılır; genellikle geri beslemeyle birlikte kullanılır.", category: "Otomasyon" },
    { id: 73, question: "Split-range kontrol ne sağlar?", options: ["Alarm üretmeyi", "İki sensör kullanmayı", "Tek kontrol sinyaliyle iki farklı aktüatörün ardışık aralıklarda çalıştırılmasını", "İki set değeri kullanmayı"], correctAnswer: 2, explanation: "Örneğin 4–12 mA ısıtma vanasını, 12–20 mA soğutma vanasını sürer; ikisi aynı anda çalışmaz.", category: "Otomasyon" },
    { id: 74, question: "PLC'nin (programlanabilir mantık denetleyici) temel çalışma döngüsü nedir?", options: ["Yalnızca alarm üretme", "Yalnızca veri kaydetme", "Sürekli analog işlem", "Girişleri oku → programı çalıştır → çıkışları yaz (tarama döngüsü)"], correctAnswer: 3, explanation: "Tarama süresi yeterince kısa olduğunda sistem gerçek zamanlı davranır; kritik girişler için kesme (interrupt) kullanılabilir.", category: "Otomasyon" },
    { id: 75, question: "SCADA sisteminin gemideki işlevi nedir?", options: ["Sistemleri merkezî olarak izlemek, kumanda etmek ve verileri kaydetmek", "Yalnızca yakıt ölçmek", "Yalnızca rota planlamak", "Yalnızca alarm çalmak"], correctAnswer: 0, explanation: "Makine kontrol odasındaki ekranlar üzerinden trend, alarm ve kumanda işlevleri sunar.", category: "Otomasyon" },
    { id: 76, question: "Alarm yönetiminde 'alarm flooding' sorunu nedir?", options: ["Alarmın gecikmesi", "Alarmın susturulması", "Tek alarmın tekrarlanması", "Kısa sürede çok sayıda alarmın gelerek operatörün öncelikleri ayırt edememesi"], correctAnswer: 3, explanation: "Tek bir arıza onlarca ardıl alarm üretebilir; önceliklendirme ve gruplama ile kök alarm öne çıkarılmalıdır.", category: "Otomasyon" },
    { id: 77, question: "Alarmların gereksiz yere susturulması (suppression) neden tehlikelidir?", options: ["Ekran yavaşlar", "Enerji tüketir", "Gerçek bir arızanın fark edilmemesine yol açar", "Kayıt bozulur"], correctAnswer: 2, explanation: "UMS çalışmada alarm sistemi tek gözcüdür; devre dışı bırakma yalnızca kayıtlı ve süreli olarak yapılmalıdır.", category: "Otomasyon" },
    { id: 78, question: "'Duty engineer alarm' sisteminin işlevi nedir?", options: ["UMS çalışmada nöbetçi mühendisi kamarasında uyarmak", "Yakıt kesmek", "Veri kaydetmek", "Makineyi durdurmak"], correctAnswer: 0, explanation: "Yanıt verilmezse alarm diğer kamaralara ve köprüüstüne yayılır; 'engineer's call' sistemi bunun parçasıdır.", category: "Otomasyon" },
    { id: 79, question: "'Dead man alarm' (kişisel emniyet alarmı) neyi sağlar?", options: ["Yakıt kontrolünü", "Sıcaklık ölçümünü", "Makine korumasını", "Makine dairesinde yalnız çalışan kişinin belirli aralıklarla varlığını teyit etmesini"], correctAnswer: 3, explanation: "Belirli sürede sıfırlanmazsa alarm verilir; bilinç kaybı gibi durumlarda hayati önem taşır.", category: "Otomasyon" },
    { id: 80, question: "Otomasyonda 'slowdown' ile 'shutdown' arasındaki fark nedir?", options: ["Slowdown durdurur", "Shutdown alarm verir", "Aynıdır", "Slowdown yükü azaltır, shutdown makineyi tamamen durdurur"], correctAnswer: 3, explanation: "Slowdown, hasarı önlerken gemiyi sevksiz bırakmamayı amaçlar; shutdown ise ani ve ağır hasar riskinde devreye girer.", category: "Otomasyon" },
    { id: 81, question: "Shutdown fonksiyonunun override edilebilmesi neden öngörülmüştür?", options: ["Alarm azaltmak için", "Bakım kolaylığı için", "Geminin emniyeti makinenin durmamasını gerektiren durumlar olabileceği için", "Yakıt tasarrufu için"], correctAnswer: 2, explanation: "Dar suda veya çarpışma riskinde kullanılır; köprüüstü kararıyla ve kayıtla yapılır.", category: "Otomasyon" },
    { id: 82, question: "Sensör kalibrasyonunun düzenli yapılmasının gerekçesi nedir?", options: ["Hız artırmak", "Enerji tasarrufu", "Estetik", "Sapma (drift) nedeniyle yanlış ölçüm ve hatalı kontrol kararlarının önlenmesi"], correctAnswer: 3, explanation: "Yanlış okuyan bir sensör hem kontrolü hem korumayı bozar; kalibrasyon kayıtları izlenebilir tutulur.", category: "Otomasyon" },
    { id: 83, question: "İki farklı sensörün aynı büyüklüğü ölçmesi (redundancy) neyi sağlar?", options: ["Maliyet düşüşü", "Sensör arızasının tespiti ve kritik ölçümde süreklilik", "Hızlı ölçüm", "Düşük güç"], correctAnswer: 1, explanation: "Sapma karşılaştırmasıyla arızalı sensör belirlenir; üçlü yedeklilikte oylama (voting) yapılabilir.", category: "Otomasyon" },
    { id: 84, question: "Basınç şalteri (pressure switch) ile transmitter arasındaki temel fark nedir?", options: ["Şalter belirli değerde kontak verir, transmitter sürekli ölçüm sinyali üretir", "Transmitter kontak verir", "Fark yoktur", "Şalter analog ölçer"], correctAnswer: 0, explanation: "Şalter basit koruma için yeterlidir; kontrol ve trend izleme için sürekli sinyal gerekir.", category: "Otomasyon" },
    { id: 85, question: "Termostatik kontrol ile PID kontrol arasındaki fark nedir?", options: ["PID aç-kapa çalışır", "Fark yoktur", "Termostat daha hassastır", "Termostat aç-kapa çalışır, PID sürekli ve orantılı düzeltme yapar"], correctAnswer: 3, explanation: "Aç-kapa kontrol sıcaklıkta salınım bırakır; PID set değerine yakın ve kararlı tutar.", category: "Otomasyon" },
    { id: 86, question: "Bir kontrol döngüsünde histerezis ayarının amacı nedir?", options: ["Basıncı düşürmek", "Hassasiyeti artırmak", "Set değeri çevresinde sık aç-kapa (chattering) davranışını önlemek", "Debiyi artırmak"], correctAnswer: 2, explanation: "Açma ve kapama eşikleri arasına fark konur; ekipmanın ömrü uzar.", category: "Otomasyon" },
    { id: 87, question: "Otomatik yakıt viskozite kontrolünde ölçülen ve kontrol edilen büyüklükler nelerdir?", options: ["Basınç ölçülür, valf kontrol edilir", "Debi ölçülür, sıcaklık kontrol edilir", "Sıcaklık ölçülür, debi kontrol edilir", "Viskozite ölçülür, ısıtıcı buhar/elektrik gücü kontrol edilir"], correctAnswer: 3, explanation: "Yakıt partileri farklı olduğundan sabit sıcaklık yeterli değildir; hedef viskozite doğrudan kontrol edilir.", category: "Otomasyon" },
    { id: 88, question: "Otomatik ana makine kontrolünde 'load program' neyi sınırlar?", options: ["Yük artış ve azalış hızını, ısıl zorlanmayı önlemek için", "Yakıt kalitesini", "Yağ basıncını", "Maksimum devri"], correctAnswer: 0, explanation: "Soğuk makinede hızlı yükleme çatlak riski yaratır; program kademeli geçişi zorunlu kılar.", category: "Otomasyon" },
    { id: 89, question: "Köprüüstü kumandasında 'telegraph' sinyalinin makine dairesinde teyit edilmesi neden gereklidir?", options: ["Alarm için", "Hız için", "Kayıt için", "Komutun alındığının ve uygulandığının karşılıklı doğrulanması için"], correctAnswer: 3, explanation: "Manuel kumandada teyit edilmeyen komut, manevrada ciddi kaza riskidir.", category: "Otomasyon" },
    { id: 90, question: "Otomasyon sisteminde veri kaydının (data logger) faydası nedir?", options: ["Yakıt ölçmek", "Alarm üretmek", "Olay öncesi parametrelerin incelenerek kök nedene ulaşılması", "Kumanda etmek"], correctAnswer: 2, explanation: "Trend kayıtları, arıza anındaki koşulların yeniden kurulmasını sağlar ve tekrarını önlemeye yardım eder.", category: "Otomasyon" },
    { id: 91, question: "UMS sınıflandırması için otomasyon sisteminde hangi işlev zorunludur?", options: ["Yalnızca uzaktan izleme", "Yalnızca uzaktan kumanda", "Alarm izleme, otomatik yedek devreye alma ve yangın algılama", "Yalnızca veri kaydı"], correctAnswer: 2, explanation: "Klas kuralları makine dairesinin gözetimsiz bırakılabilmesi için kapsamlı izleme ve koruma şartı arar.", category: "Otomasyon" },
    { id: 92, question: "Otomatik yedek pompa devreye alma (auto standby start) hangi sinyalle tetiklenir?", options: ["Debi artışı", "Seviye artışı", "Sıcaklık artışı", "Çıkış basıncının düşmesi veya çalışan pompanın durması"], correctAnswer: 3, explanation: "Düzenli test edilmelidir; devreye girmeyen yedek pompa, yağ basıncı kaybında ağır makine hasarına yol açar.", category: "Otomasyon" },
    { id: 93, question: "Otomasyon panolarının UPS ile beslenmesinin gerekçesi nedir?", options: ["Güç kesintisinde izleme ve korumanın sürmesi", "Maliyet", "Estetik", "Verim"], correctAnswer: 0, explanation: "Blackout anında kontrol sisteminin de kararması, toparlanmayı ciddi biçimde zorlaştırır.", category: "Otomasyon" },
    { id: 94, question: "Saha veri yolu (fieldbus) sistemlerinin klasik kablolamaya göre üstünlüğü nedir?", options: ["Daha az sensör", "Daha ucuz sensör", "Tek hat üzerinden çok sayıda cihazın veri ve teşhis bilgisi taşıması", "Daha hızlı aktüatör"], correctAnswer: 2, explanation: "Kablo miktarı azalır; ayrıca cihaz teşhis verisi merkezî olarak okunabilir.", category: "Otomasyon" },
    { id: 95, question: "Otomasyon sistemlerinde siber güvenliğin önemi neden artmıştır?", options: ["Hız nedeniyle", "Ağırlık nedeniyle", "Maliyet nedeniyle", "Kontrol sistemlerinin ağa bağlanmasıyla dışarıdan müdahale riskinin doğması"], correctAnswer: 3, explanation: "IMO, siber riski emniyet yönetim sisteminin parçası saymıştır; ağ ayrımı ve erişim kontrolü esastır.", category: "Otomasyon" },
    { id: 96, question: "Otomasyon yazılımı güncellemeleri neden kontrollü yapılmalıdır?", options: ["Depolama nedeniyle", "Yanlış güncelleme kritik kontrol işlevlerini bozabileceği için", "Hız nedeniyle", "Maliyet nedeniyle"], correctAnswer: 1, explanation: "Değişiklik yönetimi, geri dönüş planı ve test gerektirir; güncelleme öncesi yedek alınır.", category: "Otomasyon" },
    { id: 97, question: "Otomasyonda 'watchdog timer' neyi sağlar?", options: ["Debi ölçümü", "Veri kaydı", "Sıcaklık ölçümü", "Denetleyicinin donması hâlinde sistemi güvenli konuma alma veya yeniden başlatma"], correctAnswer: 3, explanation: "Belirli sürede sıfırlanmayan sayaç, işlemcinin çalışmadığını gösterir ve emniyet tepkisini tetikler.", category: "Otomasyon" },
    { id: 98, question: "Sensör sinyalinde gürültünün azaltılması için hangi yöntem kullanılır?", options: ["Örnekleme hızını düşürmek", "Kazancı artırmak", "Ekranlı kablo, doğru topraklama ve sinyal filtreleme", "Kabloyu uzatmak"], correctAnswer: 2, explanation: "Güç kablolarından ayrı güzergâh ve tek noktadan topraklanmış ekran, girişimi belirgin biçimde azaltır.", category: "Otomasyon" },
    { id: 99, question: "Analog sinyal kablolarının güç kablolarıyla aynı kanaldan geçirilmemesinin nedeni nedir?", options: ["Isınma", "Maliyet", "Yer darlığı", "Elektromanyetik girişimin ölçümü bozması"], correctAnswer: 3, explanation: "Özellikle VFD besleme kabloları güçlü girişim üretir; ayrım mesafesi ve dik kesişme kuralları uygulanır.", category: "Otomasyon" },
    { id: 100, question: "Kontrol döngüsünde 'ölü zaman' (dead time) neyi ifade eder?", options: ["Bir değişikliğin çıkışta görülmeye başlaması için geçen gecikmeyi", "Alarm süresini", "Bakım süresini", "Sensör arıza süresini"], correctAnswer: 0, explanation: "Uzun ölü zaman kontrolü zorlaştırır; kazanç düşürülür veya öngörücü (Smith predictor) yapılar kullanılır.", category: "Otomasyon" },
    { id: 101, question: "Bir sıcaklık döngüsünde salınım gözleniyorsa hangi ayar ilk denenir?", options: ["Türevi kaldırmak", "Set değerini yükseltmek", "Kazancı artırmak", "Kazancı azaltmak veya integral zamanını uzatmak"], correctAnswer: 3, explanation: "Salınım genellikle aşırı agresif ayardan doğar; kademeli azaltmayla kararlılık sağlanır.", category: "Otomasyon" },
    { id: 102, question: "Bir döngüde kalıcı sapma (offset) varsa ne yapılır?", options: ["Set değeri değiştirilir", "Türev artırılır", "İntegral etkisi eklenir veya artırılır", "Kazanç sıfırlanır"], correctAnswer: 2, explanation: "Yalnızca P kontrolde kalıcı hata normaldir; I terimi bu hatayı zamanla giderir.", category: "Otomasyon" },
    { id: 103, question: "Ziegler-Nichols yöntemi neyi sağlar?", options: ["PID parametreleri için başlangıç ayar değerleri", "Alarm ayarı", "Vana seçimi", "Sensör kalibrasyonu"], correctAnswer: 0, explanation: "Kritik kazanç ve periyottan türetilen değerler başlangıç noktasıdır; genellikle sahada ince ayar gerekir.", category: "Otomasyon" },
    { id: 104, question: "Otomasyon devreye alma (commissioning) sırasında 'loop check' ne yapar?", options: ["Yalnızca yazılımı test eder", "Yalnızca alarmı test eder", "Yalnızca kabloyu ölçer", "Sensörden ekrana ve ekrandan aktüatöre kadar tüm zinciri uçtan uca doğrular"], correctAnswer: 3, explanation: "Ters bağlı sinyal veya yanlış ölçekleme ancak uçtan uca testle yakalanır.", category: "Otomasyon" },
    { id: 105, question: "Bir transmitterin ölçek başlangıcının (zero) kayması hangi hatayı üretir?", options: ["Yalnızca düşük değerlerde hata", "Rastgele hata", "Yalnızca yüksek değerlerde hata", "Tüm ölçüm aralığında sabit bir kaydırma"], correctAnswer: 3, explanation: "Span hatası ise ölçek boyunca orantılı büyüyen bir sapma yaratır; kalibrasyonda ikisi ayrı ayarlanır.", category: "Otomasyon" },
    { id: 106, question: "Yağ sisi dedektörünün otomasyondaki rolü nedir?", options: ["Sıcaklık ölçmek", "Yağ seviyesi ölçmek", "Karter yağ sisi konsantrasyonunu izleyip alarm/slowdown tetiklemek", "Basınç ölçmek"], correctAnswer: 2, explanation: "Karter patlamasının önlenmesinde en kritik erken uyarıdır; sensör optikleri düzenli temizlenir.", category: "Otomasyon" },
    { id: 107, question: "Yatak sıcaklık izleme sisteminin (bearing temperature monitoring) faydası nedir?", options: ["Devir kontrolü", "Debi kontrolü", "Yakıt tasarrufu", "Yağ filmi bozulmasının erken tespiti"], correctAnswer: 3, explanation: "Sıcaklık eğilimi, hasar oluşmadan önce müdahaleye imkân verir; ani yükseliş slowdown tetikler.", category: "Otomasyon" },
    { id: 108, question: "Şaft güç ölçüm sisteminin otomasyona katkısı nedir?", options: ["Alarm üretmek", "Gerçek yükün bilinmesiyle performans ve verimlilik izlenmesi", "Yakıt kesmek", "Devir sınırlamak"], correctAnswer: 1, explanation: "SFOC ve CII hesaplarında doğrudan kullanılır; aşırı yüklenme de bu ölçümle görülür.", category: "Otomasyon" },
    { id: 109, question: "Yakıt debimetresi ile tank ölçümü arasındaki farkın izlenmesi neyi gösterebilir?", options: ["Ölçüm hatası veya yakıt kaçağını", "Basınç farkını", "Viskozite farkını", "Sıcaklık farkını"], correctAnswer: 0, explanation: "Çapraz doğrulama, hem ölçüm güvenilirliğini hem sistem bütünlüğünü kontrol eder.", category: "Otomasyon" },
    { id: 110, question: "Otomatik tank seviye ölçüm sisteminin (ATG) tankerlerdeki önemi nedir?", options: ["Isıtma kontrolü", "Havalandırma", "Yakıt tasarrufu", "Yükleme sırasında taşmayı önlemek ve miktar kontrolü sağlamak"], correctAnswer: 3, explanation: "Yüksek seviye ve taşma alarmları bağımsız olmalı; ölçüm sistemiyle aynı sensöre bağlanmamalıdır.", category: "Otomasyon" },
    { id: 111, question: "Bağımsız yüksek seviye alarmının ölçüm sisteminden ayrı olmasının gerekçesi nedir?", options: ["Doğruluk", "Maliyet", "Ölçüm sistemi arızalandığında korumanın da kaybedilmemesi", "Hız"], correctAnswer: 2, explanation: "Ortak arıza modundan kaçınmak, emniyet enstrümantasyonunun temel ilkesidir.", category: "Otomasyon" },
    { id: 112, question: "Emniyet enstrümanlı sistemlerde (SIS) 'SIL' seviyesi neyi ifade eder?", options: ["Sensör sayısını", "Kablo kesitini", "Sinyal seviyesini", "Emniyet fonksiyonunun gerekli güvenilirlik derecesini"], correctAnswer: 3, explanation: "Yüksek SIL, daha düşük arıza olasılığı ve genellikle yedekli mimari gerektirir.", category: "Otomasyon" },
    { id: 113, question: "Emniyet fonksiyonlarının kontrol fonksiyonlarından ayrılmasının nedeni nedir?", options: ["Kontrol sistemi arızalandığında emniyet korumasının etkilenmemesi", "Hız", "Basitlik", "Maliyet"], correctAnswer: 0, explanation: "Aynı denetleyiciye bağlı emniyet ve kontrol, tek arızada iki işlevi birden kaybettirir.", category: "Otomasyon" },
    { id: 114, question: "Yangın algılama sisteminde bölge (zone) ayrımının amacı nedir?", options: ["Sensör sayısını azaltmak", "Kablo azaltmak", "Maliyet düşürmek", "Alarmın hangi mahalden geldiğinin hızla belirlenmesi"], correctAnswer: 3, explanation: "Adreslenebilir sistemlerde her dedektör ayrı tanımlanır; müdahale süresi belirgin biçimde kısalır.", category: "Otomasyon" },
    { id: 115, question: "Yangın dedektörlerinin düzenli test edilmesinde hangi yöntem kullanılır?", options: ["Panoyu kapatmak", "Gerçek yangın", "Test aparatı ile duman/ısı simülasyonu", "Sensörü sökmek"], correctAnswer: 2, explanation: "Test kayıtları tutulur; devre bazında test edilerek panel yanıtı doğrulanır.", category: "Otomasyon" },
    { id: 116, question: "Otomasyonda 'trend' ekranının vardiya için değeri nedir?", options: ["Kumanda etmek", "Estetik", "Yavaş gelişen sapmaların anlık değerden çok daha erken görülmesi", "Alarm üretmek"], correctAnswer: 2, explanation: "Sabit görünen bir sıcaklık, trendde yükseliyorsa arıza gelişiyordur; vardiya devrinde trendler incelenir.", category: "Otomasyon" },
    { id: 117, question: "Otomasyon sisteminde 'set point' ile 'process value' arasındaki fark nedir?", options: ["Set point ölçülür", "Process value hedeftir", "Aynıdır", "Set point hedef, process value ise ölçülen gerçek değerdir"], correctAnswer: 3, explanation: "İkisi arasındaki fark 'hata'dır ve kontrolörün düzeltme üretmesini sağlar.", category: "Otomasyon" },
    { id: 118, question: "Manuel moda alınan bir kontrol döngüsünde operatör neyi doğrudan belirler?", options: ["Aktüatör çıkışını (vana konumunu)", "Ölçüm değerini", "Alarm sınırını", "Set değerini"], correctAnswer: 0, explanation: "Otomatik moda dönerken 'bumpless transfer' ile ani sıçrama önlenir.", category: "Otomasyon" },
    { id: 119, question: "'Bumpless transfer' neyi engeller?", options: ["Kalibrasyon kaymasını", "Alarmı", "Manuel-otomatik geçişte çıkışta ani sıçrama olmasını", "Sensör hatasını"], correctAnswer: 2, explanation: "Kontrolör, geçiş anında mevcut çıkış değerinden devam edecek şekilde iç durumunu ayarlar.", category: "Otomasyon" },
    { id: 120, question: "Otomasyon arızasında ilk sistematik adım ne olmalıdır?", options: ["Sistemi yeniden başlatmak", "Alarmı susturmak", "Kartı değiştirmek", "Sinyal zincirini sensörden çıkışa kadar ölçerek daraltmak"], correctAnswer: 3, explanation: "Çoğu arıza kablo, konnektör veya besleme kaynaklıdır; kart değişimi son adımdır.", category: "Otomasyon" },
    { id: 121, question: "Otomasyon kartlarının yedeğinin gemide bulundurulmasının gerekçesi nedir?", options: ["Maliyet", "Kritik kontrol işlevinin uzun süre devre dışı kalmaması", "Ağırlık", "Depolama"], correctAnswer: 1, explanation: "Kart tedariki uzun sürebilir; kritik ekipman listesinde yer alan sistemlerin yedeği bulundurulur.", category: "Otomasyon" },
    { id: 122, question: "Otomasyon sisteminde topraklama arızasının belirtisi ne olabilir?", options: ["Yüksek devir", "Düşük basınç", "Ekran parlaklığı", "Ölçümlerde açıklanamayan kayma ve rastgele alarmlar"], correctAnswer: 3, explanation: "Ekran ve sinyal toprağının karışması gürültü ve kaçak akım yolları yaratır.", category: "Otomasyon" },
    { id: 123, question: "Klima ve havalandırma otomasyonunda amaç nedir?", options: ["Yalnızca debi", "Yalnızca sıcaklık", "Sıcaklık, nem ve taze hava oranının kontrolüyle konfor ve ekipman koruması", "Yalnızca nem"], correctAnswer: 2, explanation: "Elektronik ekipman bulunan mahallerde nem ve sıcaklık kontrolü arıza oranını doğrudan etkiler.", category: "Otomasyon" },
    { id: 124, question: "Makine dairesi havalandırmasının otomatik kontrolünde temel girdi nedir?", options: ["Yakıt debisi", "Devir", "Deniz suyu sıcaklığı", "Mahal sıcaklığı ve makine hava ihtiyacı"], correctAnswer: 3, explanation: "Yetersiz hava, turboşarj performansını ve yanmayı doğrudan bozar; fanlar yüke göre kontrol edilir.", category: "Otomasyon" },
    { id: 125, question: "Sintine seviye otomasyonunun MARPOL açısından kritik yönü nedir?", options: ["Otomatik boşaltmanın yalnızca 15 ppm ekipmanı üzerinden yapılabilmesi", "Sıcaklık ölçümü", "Basınç ölçümü", "Debi ölçümü"], correctAnswer: 0, explanation: "Otomasyonun denize doğrudan deşarj yapabilecek şekilde kurulması ağır ihlal riskidir.", category: "Otomasyon" },
    { id: 126, question: "15 ppm ekipmanının otomatik durdurma valfinin test edilmesi neden gereklidir?", options: ["Sıcaklık için", "Basınç için", "Debi için", "Sınır aşıldığında deşarjı gerçekten kestiğinden emin olmak için"], correctAnswer: 3, explanation: "PSC denetimlerinde valf işlevi ve alarm kaydı özellikle incelenir.", category: "Otomasyon" },
    { id: 127, question: "Otomatik yakıt değişim (changeover) sisteminin faydası nedir?", options: ["Debi artırmak", "Yakıt kalitesi artırmak", "ECA girişlerinde kademeli ve kontrollü değişimi sağlayarak makine şokunu önlemek", "Basınç artırmak"], correctAnswer: 2, explanation: "Ani sıcaklık ve viskozite değişimi yakıt pompalarını sıkıştırabilir; sistem geçişi zamana yayar.", category: "Otomasyon" },
    { id: 128, question: "Otomasyonda 'interlock' ne sağlar?", options: ["Bir koşul sağlanmadan işlemin başlatılamamasını", "Alarm üretme", "Veri kaydı", "Hız artışı"], correctAnswer: 0, explanation: "Örneğin turning gear takılıyken makinenin çalıştırılamaması bir interlock'tur; emniyetin temel yapı taşıdır.", category: "Otomasyon" },
    { id: 129, question: "Interlock'ların by-pass edilmesi hangi koşulda kabul edilebilir?", options: ["Alarm azaltmak için", "Enerji tasarrufu için", "Bakımı hızlandırmak için", "Yalnızca risk değerlendirmesi, onay ve telafi edici önlemle, kayıtlı ve süreli olarak"], correctAnswer: 3, explanation: "By-pass edilmiş interlock, ciddi kazaların tekrar eden ortak nedenlerindendir.", category: "Otomasyon" },
    { id: 130, question: "Otomasyon sisteminde 'first-out' alarm mantığı ne sağlar?", options: ["Alarmları susturmak", "Alarmları geciktirmek", "Tüm alarmları göstermek", "Zincirleme alarmlar içinde ilk oluşan alarmın belirgin biçimde işaretlenmesi"], correctAnswer: 3, explanation: "Kök nedeni bulmak için hangi olayın önce gerçekleştiği kritik bilgidir.", category: "Otomasyon" },
    { id: 131, question: "Uzaktan izleme (remote monitoring) sistemlerinin kara ekiplerine faydası nedir?", options: ["Personel takibi", "Yakıt satın almak", "Performans verisinin analiz edilip bakım ve seyir kararlarının desteklenmesi", "Rota planlamak"], correctAnswer: 2, explanation: "Uzman desteği ve filo genelinde kıyaslama sağlar; ancak siber güvenlik önlemleri gerektirir.", category: "Otomasyon" },
    { id: 132, question: "Otomasyon verilerinin CII raporlamasındaki rolü nedir?", options: ["Kumanda etmek", "Bakım planlamak", "Alarm üretmek", "Yakıt tüketimi ve mesafe verisinin doğru ve izlenebilir biçimde toplanması"], correctAnswer: 3, explanation: "Veri kalitesi doğrudan derecelendirmeyi etkiler; ölçüm cihazlarının kalibrasyonu bu yüzden önemlidir.", category: "Otomasyon" },
    { id: 133, question: "Bir kontrol vanasının sızdırma sınıfı neyi belirler?", options: ["Açma hızını", "Tam kapalı konumda izin verilen kaçak miktarını", "Debi katsayısını", "Aktüatör tipini"], correctAnswer: 1, explanation: "Yakıt ve emniyet uygulamalarında sıkı kapanma (tight shut-off) sınıfı gerekir.", category: "Otomasyon" },
    { id: 134, question: "Vana debi katsayısı (Cv/Kv) neyi ifade eder?", options: ["Belirli basınç farkında geçebilecek debiyi", "Vana boyunu", "Aktüatör gücünü", "Vana ağırlığını"], correctAnswer: 0, explanation: "Doğru boyutlandırma kontrol kalitesini belirler; büyük seçilen vana ancak dar bir açıklıkta çalışır ve kontrol kabalaşır.", category: "Otomasyon" },
    { id: 135, question: "Kontrol vanasının çok büyük seçilmesinin sonucu nedir?", options: ["Daha az basınç kaybı", "Daha uzun ömür", "Daha iyi kontrol", "Vananın dar açıklıkta çalışması ve kontrol hassasiyetinin düşmesi"], correctAnswer: 3, explanation: "Ayrıca kavitasyon ve gürültü artabilir; tasarım debisi aralığına uygun seçim gerekir.", category: "Otomasyon" },
    { id: 136, question: "Kontrol vanasında kavitasyon oluşursa hangi belirti görülür?", options: ["Basınç artışı", "Sessiz çalışma", "Çakıl sesi benzeri gürültü ve iç yüzey aşınması", "Debi artışı"], correctAnswer: 2, explanation: "Basınç, akışkanın buhar basıncının altına düştüğünde oluşur; çok kademeli trim ile önlenir.", category: "Otomasyon" },
    { id: 137, question: "Pnömatik kontrol havasının kuru ve yağsız olması neden gereklidir?", options: ["Debi için", "Sıcaklık için", "Basınç için", "Nem ve yağın valf ve pozisyonerlerde yapışma ve arıza yaratması nedeniyle"], correctAnswer: 3, explanation: "Kurutucu ve yağ ayırıcı bakımı ihmal edilirse çok sayıda saha cihazı aynı anda arızalanabilir.", category: "Otomasyon" },
    { id: 138, question: "Bir I/P dönüştürücü (current to pneumatic) ne yapar?", options: ["4–20 mA sinyalini orantılı hava basıncına dönüştürür", "Akımı gerilime çevirir", "Debiyi ölçer", "Basıncı akıma çevirir"], correctAnswer: 0, explanation: "Elektronik kontrol sinyali ile pnömatik aktüatör arasındaki arayüzdür; hava kalitesi performansını doğrudan etkiler.", category: "Otomasyon" },
    { id: 139, question: "Otomasyonda kalibrasyon sertifikalarının izlenebilir (traceable) olması ne demektir?", options: ["Renkli olması", "Onaylı olması", "Dijital olması", "Kullanılan referansın ulusal/uluslararası standarda dayanması"], correctAnswer: 3, explanation: "İzlenebilirlik olmadan ölçüm doğruluğu kanıtlanamaz; denetimlerde sertifikalar istenir.", category: "Otomasyon" },
    { id: 140, question: "Otomatik kontrolün insan gözetimini ortadan kaldırmamasının nedeni nedir?", options: ["Yasal zorunluluk yok", "Maliyet", "Sistemin öngörmediği durumlarda karar ve müdahalenin insana ait olması", "Hız"], correctAnswer: 2, explanation: "Otomasyon rutini üstlenir; anormal ve belirsiz durumlarda mühendisin durum değerlendirmesi belirleyicidir.", category: "Otomasyon" },
    { id: 141, question: "Otomasyona aşırı güvenmenin (automation complacency) riski nedir?", options: ["Veri kaybı", "Hız kaybı", "Operatörün sistemi sorgulamayı bırakıp sapmaları fark edememesi", "Enerji kaybı"], correctAnswer: 2, explanation: "Bu yüzden düzenli tur kontrolleri ve manuel doğrulama alışkanlığı sürdürülür.", category: "Otomasyon" },
    { id: 142, question: "Makine kontrol odasında düzenli 'tur kontrolü' (rounds) neden hâlâ gereklidir?", options: ["Kayıt için", "Denetim için", "Gelenek", "Sensörlerin görmediği sızıntı, ses, titreşim ve koku gibi belirtilerin fark edilmesi"], correctAnswer: 3, explanation: "Otomasyon yalnızca ölçtüğünü bilir; insan duyuları erken arıza tespitinde tamamlayıcıdır.", category: "Otomasyon" },
    { id: 143, question: "Otomasyon sistemi arızalandığında makine dairesi nasıl işletilir?", options: ["Sürekli gözetimli (manned) çalışmaya geçilir", "Yalnızca uzaktan izlenir", "Yük azaltılır", "Sefer durdurulur"], correctAnswer: 0, explanation: "UMS koşulları sağlanmıyorsa vardiya tutulur; durum jurnale ve gerekiyorsa klasa bildirilir.", category: "Otomasyon" },
    { id: 144, question: "Otomasyon alarm listesinin düzenli gözden geçirilmesi neyi sağlar?", options: ["Kablo tasarrufunu", "Ekran hızını", "Gereksiz ve tekrarlayan alarmların ayıklanarak sistemin güvenilir kalmasını", "Enerji tasarrufunu"], correctAnswer: 2, explanation: "Sürekli çalan anlamsız alarmlar, operatörü tüm alarmlara duyarsızlaştırır.", category: "Otomasyon" },
    { id: 145, question: "Bir alarmın öncelik seviyesinin doğru belirlenmesi neye göre yapılır?", options: ["Sensör tipine", "Kablo uzunluğuna", "Alarm sayısına", "Sonucun ciddiyeti ve müdahale için kalan süreye"], correctAnswer: 3, explanation: "Yüksek öncelikli alarmlar acil müdahale gerektirir; düşük öncelikliler bilgilendirme niteliğindedir.", category: "Otomasyon" },
    { id: 146, question: "Otomasyon sisteminde saat senkronizasyonunun önemi nedir?", options: ["Estetik", "Olay kayıtlarının doğru sırayla incelenebilmesi", "Hız", "Depolama"], correctAnswer: 1, explanation: "Farklı sistemlerin saatleri uyumsuzsa kök neden analizinde olay sırası yanlış kurulur.", category: "Otomasyon" },
    { id: 147, question: "Bir kontrol döngüsünün 'auto' modda bırakılmasının ön koşulu nedir?", options: ["Alarmın kapalı olması", "Vananın açık olması", "Set değerinin yüksek olması", "Ölçümün güvenilir ve aktüatörün işlevsel olması"], correctAnswer: 3, explanation: "Arızalı sensörle otomatik mod, kontrolörün yanlış yönde düzeltme yapmasına yol açar.", category: "Otomasyon" },
    { id: 148, question: "Sensör arızası şüphesinde hangi çapraz kontrol yapılır?", options: ["Devreyi kapatmak", "Alarmı susturmak", "Bağımsız bir gösterge veya taşınabilir ölçüm cihazıyla karşılaştırmak", "Kontrolörü değiştirmek"], correctAnswer: 2, explanation: "Yerel manometre/termometre ile karşılaştırma en hızlı doğrulama yöntemidir.", category: "Otomasyon" },
    { id: 149, question: "Otomasyon değişikliklerinin belgelenmesi neden zorunludur?", options: ["Maliyet için", "Stok için", "Denetim için yeterli", "Sonraki arıza aramalarında ve devir teslimde doğru bilginin bulunması için"], correctAnswer: 3, explanation: "Güncellenmemiş şema ve ayar kayıtları, arıza süresini kat kat uzatır.", category: "Otomasyon" },
    { id: 150, question: "Otomasyonun makine dairesi emniyetine en büyük katkısı nedir?", options: ["Tehlikeli sapmaları insandan hızlı algılayıp koruma tepkisini otomatik başlatmak", "Maliyet düşürmek", "Gürültü azaltmak", "Personel azaltmak"], correctAnswer: 0, explanation: "Yağ basıncı kaybı gibi saniyeler içinde hasar yaratan olaylarda otomatik koruma belirleyicidir.", category: "Otomasyon" },
  ],
  maintenance: [
    { id: 51, question: "Planlı bakım sisteminin (PMS) temel amacı nedir?", options: ["Personel azaltmak", "Yedek parça satmak", "Maliyeti artırmak", "Arıza oluşmadan önce bakımı planlayarak güvenilirliği sürdürmek"], correctAnswer: 3, explanation: "PMS; görevleri, aralıkları, kayıtları ve yedek parça takibini tek sistemde toplar ve ISM kapsamında zorunludur.", category: "Bakım" },
    { id: 52, question: "Arıza sonrası bakımın (breakdown maintenance) temel dezavantajı nedir?", options: ["Maliyetinin öngörülebilir olması", "Planlama gerektirmesi", "Arızanın zamanlaması seçilemediği için ikincil hasar ve uzun duruş riski", "Yedek parça gerektirmemesi"], correctAnswer: 2, explanation: "Kritik olmayan ve yedeği bulunan basit ekipmanda kabul edilebilir; kritik ekipmanda uygun değildir.", category: "Bakım" },
    { id: 53, question: "Durum bazlı bakımın (condition-based) periyodik bakıma üstünlüğü nedir?", options: ["Ekipmanın gerçek durumuna göre müdahale ederek gereksiz sökümü önlemesi", "Daha basit olması", "Kayıt gerektirmemesi", "Ölçüm gerektirmemesi"], correctAnswer: 0, explanation: "Gereksiz açma-kapama yeni arıza riski yaratır; ölçüm verisi bakımı gerçekten gerektiği anda tetikler.", category: "Bakım" },
    { id: 54, question: "Kestirimci bakımda kullanılan başlıca teknikler hangileridir?", options: ["Yalnızca basınç ölçümü", "Yalnızca ses dinleme", "Yalnızca gözle muayene", "Titreşim analizi, yağ analizi ve termografi"], correctAnswer: 3, explanation: "Bu teknikler arızanın gelişme evresinde belirti verir; müdahale planlı bir zamana alınabilir.", category: "Bakım" },
    { id: 55, question: "Titreşim ölçümünde 1× devir frekansındaki yüksek genlik neyi düşündürür?", options: ["Kaplin gevşekliğini", "Kavitasyonu", "Rulman hasarını", "Balanssızlığı"], correctAnswer: 3, explanation: "Balanssızlık devir frekansında baskındır; hizasızlık genellikle 2× bileşende belirginleşir.", category: "Bakım" },
    { id: 56, question: "Titreşim spektrumunda 2× devir bileşeninin baskın olması neyi gösterir?", options: ["Gevşek cıvata", "Balanssızlık", "Kaplin hizasızlığı", "Rulman hasarı"], correctAnswer: 2, explanation: "Eksenel yönde de yüksek genlik görülmesi açısal hizasızlığın tipik göstergesidir.", category: "Bakım" },
    { id: 57, question: "Yağ analizinde 'PQ index' değeri neyi ölçer?", options: ["Su içeriğini", "Asitliği", "Viskoziteyi", "Yağdaki ferromanyetik parçacık miktarını"], correctAnswer: 3, explanation: "Artan değer, aşınan çelik yüzeylerden partikül salındığını gösterir; eğilim izlemesi kritiktir.", category: "Bakım" },
    { id: 58, question: "Yağın TAN (toplam asit sayısı) değerinin yükselmesi neyi gösterir?", options: ["Su karışmasını", "Oksidasyon ve yağın bozulmasını", "Yakıt karışmasını", "Yeni yağ eklendiğini"], correctAnswer: 1, explanation: "Asitleşen yağ korozyon yapar ve yağlama kabiliyetini yitirir; sınır aşıldığında yağ yenilenir.", category: "Bakım" },
    { id: 59, question: "Silindir yağının TBN değerinin düşmesi neyi gösterir?", options: ["Alkali rezervin kükürt asidini nötralize ederek tükendiğini", "Su karıştığını", "Viskozitenin arttığını", "Yağın tazelendiğini"], correctAnswer: 0, explanation: "Süzülen yağ (scrape-down) analizinde TBN ve demir içeriği birlikte izlenerek besleme oranı ayarlanır.", category: "Bakım" },
    { id: 60, question: "Termografi ile yapılan kontrolde hangi bulgu acil müdahale gerektirir?", options: ["Düşük sıcaklık", "Sabit sıcaklık", "Homojen sıcaklık", "Bir fazın diğerlerine göre belirgin biçimde sıcak olması"], correctAnswer: 3, explanation: "Faz dengesizliği veya gevşek bağlantı işaretidir; ark ve yangına ilerleyebilir.", category: "Bakım" },
    { id: 61, question: "Ana makine piston sökümü (overhaul) aralığı neye göre belirlenir?", options: ["Yakıt fiyatına", "Takvim yılına", "Üretici çalışma saati önerisi ve ölçülen aşınma durumuna", "Gemi yaşına"], correctAnswer: 2, explanation: "Ölçüm verisi iyi olan makinelerde aralık uzatılabilir; klas onayıyla durum bazlı programa geçilebilir.", category: "Bakım" },
    { id: 62, question: "Silindir gömleğinde aşınma ölçümü hangi amaçla yapılır?", options: ["Renk için", "Sertlik için", "Ağırlık için", "Ovalleşme ve çap artışını izleyerek gömlek ömrünü belirlemek"], correctAnswer: 3, explanation: "Ölçümler farklı yükseklik ve yönlerde alınır; sınır aşıldığında gömlek yenilenir.", category: "Bakım" },
    { id: 63, question: "Gömlek çapı 600 mm iken ölçülen değer 604.8 mm ise aşınma yüzde kaçtır?", options: ["%0.8", "%1.2", "%1.6", "%0.4"], correctAnswer: 0, explanation: "Aşınma = 4.8/600 = 0.008 → %0.8; genel sınır yaklaşık %0.8–1.0 mertebesindedir.", category: "Bakım" },
    { id: 64, question: "Segman açıklığının (ring gap) ölçülmesinin nedeni nedir?", options: ["Renk kontrolü", "Sertlik kontrolü", "Ağırlık kontrolü", "Aşınma ile büyüyen açıklığın sızdırmazlığı bozmasının izlenmesi"], correctAnswer: 3, explanation: "Büyüyen açıklık sıkıştırma kaybı ve blow-by yaratır; sınır aşıldığında segman değiştirilir.", category: "Bakım" },
    { id: 65, question: "Yatak boşluğunun (bearing clearance) ölçülmesinde hangi yöntem kullanılır?", options: ["Komparatör", "Kumpas", "Kurşun tel veya plastigage ile sıkıştırma ölçümü", "Mikrometre"], correctAnswer: 2, explanation: "Ezilen malzemenin kalınlığı boşluğu verir; ölçüm üretici toleransıyla karşılaştırılır.", category: "Bakım" },
    { id: 66, question: "Yatak boşluğunun toleransın üstünde olması neye yol açar?", options: ["Verim artışı", "Yağ basıncı artışı", "Yağ basıncı düşüşü ve darbe yükleri", "Sıcaklık düşüşü"], correctAnswer: 2, explanation: "Aşırı boşluk yağ kaçağı ve film kaybı yaratır; yatak hızla hasar görür.", category: "Bakım" },
    { id: 67, question: "Krank sapması (crankshaft deflection) ölçümünün amacı nedir?", options: ["Devir ölçmek", "Basınç ölçmek", "Ağırlık ölçmek", "Gövde/yatak hizasındaki bozulmayı tespit etmek"], correctAnswer: 3, explanation: "Bir tur boyunca karşılıklı ölçümler alınır; sınır dışı sapma yatak veya gövde deformasyonunu gösterir.", category: "Bakım" },
    { id: 68, question: "Krank sapması ölçümü hangi koşulda yapılmalıdır?", options: ["Makine soğukken ve gemi mümkün olduğunca dengeliyken", "Manevrada", "Yük altında", "Makine tam sıcakken"], correctAnswer: 0, explanation: "Ölçüm koşulları kayda geçirilir; farklı koşullarda alınan değerler karşılaştırılamaz.", category: "Bakım" },
    { id: 69, question: "Supap kursu ve boşluk (tappet clearance) ayarının önemi nedir?", options: ["Devir", "Yakıt kalitesi", "Supap zamanlamasının ve tam kapanmanın sağlanması", "Yağ basıncı"], correctAnswer: 2, explanation: "Az boşluk supabı tam kapatmaz ve yanma gazı kaçağıyla supabı yakar; fazla boşluk vuruntu ve zamanlama kaybı yaratır.", category: "Bakım" },
    { id: 70, question: "Egzoz supabında 'burning' (yanma) hasarının tipik nedeni nedir?", options: ["Düşük sıcaklık", "Fazla yağ", "Aşırı boşluk", "Tam oturmama nedeniyle sıcak gaz kaçağı"], correctAnswer: 3, explanation: "Kaçak yüzeyde lokal aşırı ısınma yaratır; supap ve yuva taşlanarak veya yenilenerek onarılır.", category: "Bakım" },
    { id: 71, question: "Enjektörlerin test tezgâhında kontrolünde neye bakılır?", options: ["Ağırlık", "Açma basıncı, püskürtme deseni ve damlama olup olmadığı", "Renk", "Uzunluk"], correctAnswer: 1, explanation: "Damlatan enjektör eksik yanma ve kurum üretir; açma basıncı düşükse atomizasyon bozulur.", category: "Bakım" },
    { id: 72, question: "Yakıt pompası eleman aşınmasının belirtisi nedir?", options: ["Yağ basıncının artması", "Devir artışı", "Yakıt sıcaklığının artması", "Enjeksiyon basıncının ve güç dengesinin düşmesi"], correctAnswer: 3, explanation: "Aşınan piston-gömlek çifti iç kaçak yapar; silindirler arası yük dengesizliği gözlenir.", category: "Bakım" },
    { id: 73, question: "Turboşarj yatak bakımında en kritik nokta nedir?", options: ["Boyut", "Renk", "Yağ kalitesi ve besleme sürekliliği", "Ağırlık"], correctAnswer: 2, explanation: "Çok yüksek devirde çalışan yataklar kısa yağ kesintisinde dahi hasar görür; durdurma sonrası yağlama sürdürülür.", category: "Bakım" },
    { id: 74, question: "Turboşarj nozul halkasının kirlenmesi hangi sonuca yol açar?", options: ["Yağ basıncı artışı", "Titreşim azalması", "Devir artışı", "Verim düşüşü, dolgu basıncı azalması ve egzoz sıcaklığı artışı"], correctAnswer: 3, explanation: "Düzenli su yıkaması ve periyodik temizlik performansı korur.", category: "Bakım" },
    { id: 75, question: "Isı eşanjörü temizliği için plakalı tipte hangi yöntem kullanılır?", options: ["Sökerek mekanik/kimyasal temizlik veya yerinde kimyasal sirkülasyon (CIP)", "Sadece su tutmak", "Sadece boyamak", "Sadece hava üflemek"], correctAnswer: 0, explanation: "Contalar kontrol edilip gerekiyorsa yenilenir; kimyasal seçimi plaka malzemesine uygun olmalıdır.", category: "Bakım" },
    { id: 76, question: "Deniz suyu tarafındaki boruların temizliğinde kimyasal kullanılırken dikkat edilmesi gereken nedir?", options: ["Sıcaklık", "Debi", "Renk", "Malzeme uyumluluğu ve atığın MARPOL'e uygun bertarafı"], correctAnswer: 3, explanation: "Yanlış kimyasal boruyu incelterek kaçak yaratır; kullanılan çözelti kıyı tesisine teslim edilir.", category: "Bakım" },
    { id: 77, question: "Anotların (sacrificial anode) değiştirilme ölçütü nedir?", options: ["Konum", "Renk değişimi", "Kütlesinin belirli oranda tükenmiş olması", "Yaş"], correctAnswer: 2, explanation: "Genellikle yaklaşık yarısı tükendiğinde değiştirilir; tükenmiş anot koruma sağlamaz.", category: "Bakım" },
    { id: 78, question: "Havuzlama (dry-dock) aralığı klas kurallarına göre tipik olarak nedir?", options: ["Beş yılda iki kez, aralarda en fazla 36 ay olacak şekilde", "On yılda bir", "İki yılda bir", "Her yıl"], correctAnswer: 0, explanation: "Su altı muayenesi (UWILD) belirli gemilerde bir havuzlamanın yerine geçebilir.", category: "Bakım" },
    { id: 79, question: "Havuzlamada yapılan temel makine işleri hangileridir?", options: ["Yalnızca kaynak", "Yalnızca temizlik", "Yalnızca boyama", "Kuyruk şaftı, pervane, deniz sandığı, dip valfleri ve dümen yatağı muayenesi"], correctAnswer: 3, explanation: "Su altında erişilemeyen bileşenler bu dönemde ölçülür ve gerekiyorsa yenilenir.", category: "Bakım" },
    { id: 80, question: "Kuyruk şaftı yatak aşınmasının ölçümü (poker gauge) neyi gösterir?", options: ["Şaft ağırlığını", "Pervane hatvesini", "Şaft uzunluğunu", "Yatak boşluğunun tolerans içinde olup olmadığını"], correctAnswer: 3, explanation: "Aşınma sınırı aşıldığında yatak yenilenir; ölçüm havuzlama raporunda kayda geçirilir.", category: "Bakım" },
    { id: 81, question: "Sürekli makine sörveyi (CMS) sisteminin faydası nedir?", options: ["Kayıt gerektirmemesi", "Sörveyi kaldırması", "Muayenelerin beş yıla yayılarak planlı biçimde yapılabilmesi", "Maliyeti artırması"], correctAnswer: 2, explanation: "Her yıl belirli bir yüzdesi tamamlanır; böylece havuzlamada yığılma önlenir.", category: "Bakım" },
    { id: 82, question: "Baş mühendisin yapabileceği sörveylerde (chief engineer surveys) temel koşul nedir?", options: ["Yalnızca gemi yaşı", "Yalnızca liman izni", "Yalnızca deneyim", "Klas tarafından yetkilendirilmiş olmak ve kayıtları usulüne uygun tutmak"], correctAnswer: 3, explanation: "Belirli ekipman kalemleri, uygun raporlama ve fotoğraf kaydıyla gemide tamamlanabilir.", category: "Bakım" },
    { id: 83, question: "Yedek parça envanterinde 'kritik yedek' nasıl belirlenir?", options: ["En pahalı parçalar", "Arızası ciddi sonuç doğuran ve tedariki uzun süren parçalar", "En hafif parçalar", "En sık kullanılanlar"], correctAnswer: 1, explanation: "Klas ayrıca asgari yedek listesi tanımlar; kritik ekipman analizi bunu tamamlar.", category: "Bakım" },
    { id: 84, question: "Yedek parçaların doğru saklanmasında en önemli husus nedir?", options: ["Korozyon ve nemden korunma ile doğru etiketleme", "Ağırlık dağılımı", "Ambalaj boyutu", "Renk kodlaması"], correctAnswer: 0, explanation: "Yanlış saklanan rulman veya conta, kullanım anında hasarlı çıkabilir; koruyucu yağ ve kapalı ambalaj korunur.", category: "Bakım" },
    { id: 85, question: "Bakım sırasında kullanılan tork anahtarının kalibrasyonu neden önemlidir?", options: ["Renk için", "Hız için", "Ağırlık için", "Cıvata ön yükünün doğru uygulanması ve bağlantı bütünlüğü için"], correctAnswer: 3, explanation: "Eksik tork gevşemeye, fazla tork cıvata kopmasına yol açar; kritik bağlantılarda hidrolik gerdirme kullanılır.", category: "Bakım" },
    { id: 86, question: "Hidrolik cıvata gerdirme yönteminin avantajı nedir?", options: ["Alet gerektirmemesi", "Daha ucuz olması", "Ön yükün doğrudan ve sürtünmeden bağımsız biçimde uygulanabilmesi", "Daha hızlı olması"], correctAnswer: 2, explanation: "Tork yöntemi sürtünme katsayısına bağlıdır ve dağılım gösterir; büyük cıvatalarda gerdirme tercih edilir.", category: "Bakım" },
    { id: 87, question: "Conta (gasket) değişiminde yüzey hazırlığının önemi nedir?", options: ["Ağırlık", "Isı", "Estetik", "Kalıntı ve çizik sızdırmazlığı doğrudan bozduğu için"], correctAnswer: 3, explanation: "Eski conta kalıntısı temizlenmeden yapılan montaj kısa sürede kaçak verir.", category: "Bakım" },
    { id: 88, question: "O-ring montajında en yaygın hata nedir?", options: ["Keskin kenarda kesilmesi veya yanlış ölçü kullanılması", "Yağlamak", "Temizlemek", "Fazla sıkma"], correctAnswer: 0, explanation: "Montaj sırasında uygun yağlama ve pah kullanımı kesilmeyi önler; ölçü ve malzeme uyumu şarttır.", category: "Bakım" },
    { id: 89, question: "Rulman montajında ısıtma yönteminin (induction heater) amacı nedir?", options: ["Sertleştirmek", "Temizlemek", "Yağlamak", "Termal genleşmeyle rulmanı zorlamadan mile geçirmek"], correctAnswer: 3, explanation: "Çekiçle zorlama bilye yuvalarında kalıcı iz bırakır ve erken arıza yaratır.", category: "Bakım" },
    { id: 90, question: "Rulman arızalarının en yaygın nedeni nedir?", options: ["Düşük sıcaklık", "Üretim hatası", "Yetersiz/uygunsuz yağlama ve kirlenme", "Yüksek devir"], correctAnswer: 2, explanation: "İstatistiklerde yağlama kaynaklı arızalar ilk sıradadır; doğru gres tipi ve miktarı belirleyicidir.", category: "Bakım" },
    { id: 91, question: "Kaplin hizalamasında sıcak çalışma koşulunun dikkate alınmasının nedeni nedir?", options: ["Titreşim ölçümü", "Estetik", "Isınmayla makinenin yükselerek hizanın değişmesi", "Ağırlık"], correctAnswer: 2, explanation: "Soğukken kasıtlı bir ofset verilir; çalışma sıcaklığında hiza doğru konuma gelir.", category: "Bakım" },
    { id: 92, question: "Şaft hizalama ölçümünde lazer sistemin komparatöre üstünlüğü nedir?", options: ["Kalibrasyon gerektirmemesi", "Elektrik gerektirmemesi", "Ucuz olması", "Daha yüksek doğruluk ve hızlı ölçüm"], correctAnswer: 3, explanation: "Mekanik ölçüde sehim ve okuma hatası büyükken lazer sistem sonucu doğrudan hesaplar.", category: "Bakım" },
    { id: 93, question: "Kaynak onarımı yapılacak bir makine parçasında ilk değerlendirme nedir?", options: ["Malzemenin kaynak kabiliyeti ve onarımın klas onayı gerektirip gerektirmediği", "Ağırlık", "Maliyet", "Renk uygunluğu"], correctAnswer: 0, explanation: "Dökme demir ve yüksek alaşımlı çelikler özel prosedür ister; yapısal parçalarda klas onayı gerekir.", category: "Bakım" },
    { id: 94, question: "Tahribatsız muayene (NDT) yöntemlerinden penetrant testi neyi bulur?", options: ["Sertliği", "İç boşlukları", "Yüzeye açık çatlakları", "Kalınlık kaybını"], correctAnswer: 2, explanation: "Manyetik parçacık yüzey ve yüzeye yakın, ultrasonik ve radyografi ise iç kusurları tespit eder.", category: "Bakım" },
    { id: 95, question: "Ultrasonik kalınlık ölçümü hangi amaçla kullanılır?", options: ["Sertlik ölçmek", "Renk ölçmek", "Çatlak bulmak", "Korozyon nedeniyle incelen sac ve boru kalınlığını ölçmek"], correctAnswer: 3, explanation: "Yenileme kararları bu ölçümlere dayanır; ölçüm noktaları haritalanarak eğilim izlenir.", category: "Bakım" },
    { id: 96, question: "Bakım işine başlamadan önce yapılması gereken ilk adım nedir?", options: ["Parçayı sökmek", "Risk değerlendirmesi ve gereken izinlerin alınması", "Alet hazırlamak", "Fotoğraf çekmek"], correctAnswer: 1, explanation: "İzin sistemi, enerji izolasyonu ve KKD gereklerinin doğrulanmasını sağlar.", category: "Bakım" },
    { id: 97, question: "Bakım sonrası devreye alma (recommissioning) sırasında ne yapılır?", options: ["Sistem kapatılır", "Alarm devre dışı bırakılır", "Doğrudan tam yük verilir", "Kademeli yükleme ile sızdırmazlık, sıcaklık ve titreşim izlenir"], correctAnswer: 3, explanation: "İlk çalıştırmada montaj hataları en çok bu aşamada ortaya çıkar; yakın gözetim şarttır.", category: "Bakım" },
    { id: 98, question: "Bakım kayıtlarında 'as found' ve 'as left' ölçümlerinin kaydedilmesi neyi sağlar?", options: ["Stok azaltma", "Estetik", "Aşınma hızının hesaplanabilmesi ve sonraki bakım aralığının planlanması", "Maliyet düşüşü"], correctAnswer: 2, explanation: "İki ölçüm arasındaki fark, çalışma saatine bölünerek aşınma oranı bulunur.", category: "Bakım" },
    { id: 99, question: "Bir gömlek 12,000 saatte 2.4 mm aşındıysa saatlik aşınma oranı kaç mm/1,000 saattir?", options: ["0.3 mm", "0.5 mm", "0.1 mm", "0.2 mm"], correctAnswer: 3, explanation: "2.4/12 = 0.2 mm/1,000 saat; sınır değere kalan süre bu oranla tahmin edilir.", category: "Bakım" },
    { id: 100, question: "Aşınma oranı 0.2 mm/1,000 saat ve kalan izin verilen aşınma 3.0 mm ise kalan ömür yaklaşık kaç saattir?", options: ["15,000 saat", "6,000 saat", "9,000 saat", "12,000 saat"], correctAnswer: 0, explanation: "3.0/0.2 = 15 → 15 × 1,000 = 15,000 saat.", category: "Bakım" },
    { id: 101, question: "Makine çalışma saatlerinin doğru kaydedilmesi neden önemlidir?", options: ["Personel için", "Denetim için", "Yakıt hesabı için", "Bakım görevlerinin doğru zamanda tetiklenmesi için"], correctAnswer: 3, explanation: "Yanlış saat kaydı, bakımın erken veya çok geç yapılmasına yol açar.", category: "Bakım" },
    { id: 102, question: "Günde ortalama 20 saat çalışan bir jeneratör 6,000 saatlik bakıma yaklaşık kaç gün sonra ulaşır?", options: ["200 gün", "250 gün", "300 gün", "365 gün"], correctAnswer: 2, explanation: "6,000/20 = 300 gün; planlama bu tahmine göre yapılır.", category: "Bakım" },
    { id: 103, question: "Üç jeneratörün çalışma saatlerinin dengelenmesi neden istenir?", options: ["Bakımların aynı döneme yığılmaması ve aşınmanın dengelenmesi", "Gürültü", "Titreşim", "Yakıt tasarrufu"], correctAnswer: 0, explanation: "Dönüşümlü çalıştırma hem yedekliliği hem planlama esnekliğini korur.", category: "Bakım" },
    { id: 104, question: "Bakım planlamasında 'kritiklik analizi' neyi belirler?", options: ["Personel sayısını", "Yakıt tüketimini", "Parça fiyatını", "Hangi ekipmanın hangi bakım stratejisiyle yönetileceğini"], correctAnswer: 3, explanation: "Kritik ekipman kestirimci/önleyici, kritik olmayan ise arıza sonrası bakımla yönetilebilir.", category: "Bakım" },
    { id: 105, question: "Kök neden analizinde '5 neden' yöntemi neyi hedefler?", options: ["Maliyeti hesaplamak", "Süreyi ölçmek", "Sorumluyu bulmak", "Yüzeydeki belirtinin altındaki sistemik nedene ulaşmak"], correctAnswer: 3, explanation: "'Rulman bozuldu' yerine 'yağlama programı ekipmana tanımlanmamış' gibi bir nedene ulaşmak kalıcı çözüm sağlar.", category: "Bakım" },
    { id: 106, question: "Aynı arızanın tekrarlaması neyi gösterir?", options: ["Personel değişimini", "Normal aşınmayı", "Kök nedenin giderilmemiş olduğunu", "Yedek parça kalitesini"], correctAnswer: 2, explanation: "Tekrarlayan arıza kayıtları, bakım sisteminin gözden geçirilmesi gereken en güçlü sinyalidir.", category: "Bakım" },
    { id: 107, question: "Bakım sonrası kalan yabancı cisim (FOD) riski nasıl önlenir?", options: ["Kapağı hemen kapatarak", "Fotoğraf çekerek", "Hızlı çalışarak", "Alet ve parça sayımı ile çalışma alanının kontrollü kapatılmasıyla"], correctAnswer: 3, explanation: "Karter veya süpürme kutusunda unutulan bir alet çok ağır hasar yaratabilir.", category: "Bakım" },
    { id: 108, question: "Süpürme kutusu (scavenge space) muayenesinde neye bakılır?", options: ["Yağ seviyesine", "Segman durumu, gömlek yağ filmi, kurum birikimi ve kaçak izlerine", "Basınca", "Devre"], correctAnswer: 1, explanation: "Bu muayene, silindir açılmadan içerideki durumu değerlendirmenin en etkili yoludur.", category: "Bakım" },
    { id: 109, question: "Süpürme kutusunda aşırı kurum birikimi hangi riski yaratır?", options: ["Süpürme kutusu yangını", "Debi artışı", "Titreşim", "Basınç düşüşü"], correctAnswer: 0, explanation: "Blow-by ve yağlı kurum tutuşabilir; sıcaklık artışı ve turbo devir düşüşü tipik belirtilerdir.", category: "Bakım" },
    { id: 110, question: "Silindir yağı besleme oranının optimize edilmesi neyi sağlar?", options: ["Devir artışı", "Basınç artışı", "Yakıt tasarrufu", "Yeterli koruma sağlarken gereksiz yağ tüketimi ve birikim oluşmaması"], correctAnswer: 3, explanation: "Az besleme aşınma, fazla besleme kalsiyum birikimi ve süpürme kutusu kirlenmesi yaratır.", category: "Bakım" },
    { id: 111, question: "Scrape-down yağ analizinin amacı nedir?", options: ["Basınç ölçmek", "Yakıt kalitesini ölçmek", "Silindir aşınmasını ve yağ besleme oranının uygunluğunu değerlendirmek", "Su içeriğini ölçmek"], correctAnswer: 2, explanation: "Demir içeriği ve kalan TBN, besleme oranı kararının veri temelidir.", category: "Bakım" },
    { id: 112, question: "Bakımda üretici el kitabına uyulmasının gerekçesi nedir?", options: ["Maliyet", "Hız", "Yasal zorunluluk yok", "Tolerans, tork ve prosedürlerin ekipmana özgü olması"], correctAnswer: 3, explanation: "Genel uygulamalar ekipmana uymayabilir; garanti ve klas kabulü de el kitabına uyuma bağlıdır.", category: "Bakım" },
    { id: 113, question: "Orijinal olmayan yedek parça kullanımının riski nedir?", options: ["Malzeme ve tolerans uyumsuzluğu nedeniyle erken arıza", "Ağırlık farkı", "Ambalaj farkı", "Renk farkı"], correctAnswer: 0, explanation: "Kritik parçalarda onaylı eşdeğer kullanımı klas ve üretici kabulüne bağlıdır.", category: "Bakım" },
    { id: 114, question: "Bakım işlerinde iş emri (work order) sisteminin faydası nedir?", options: ["Personel değerlendirmesi", "Yakıt hesabı", "Kâğıt tasarrufu", "İşin planlanması, kaynak tahsisi ve tamamlanmasının izlenmesi"], correctAnswer: 3, explanation: "Açık iş emirleri geciken bakımları görünür kılar ve önceliklendirmeyi mümkün kılar.", category: "Bakım" },
    { id: 115, question: "Geciken (overdue) bakım görevlerinin yönetiminde doğru yaklaşım nedir?", options: ["Aralığı uzatmak", "Kayıttan silmek", "Gerekçe ve risk değerlendirmesiyle ertelemeyi belgelemek ve yeni tarih vermek", "Görevi kapatmak"], correctAnswer: 2, explanation: "Belgesiz erteleme ISM denetimlerinde uygunsuzluk oluşturur; risk kabulü yetkili tarafından yapılmalıdır.", category: "Bakım" },
    { id: 116, question: "Bakımda 'shutdown penceresi' planlamasının amacı nedir?", options: ["Liman ücreti", "Personel izni", "Ekipmanın durdurulabileceği uygun zaman diliminin sefer planına göre belirlenmesi", "Yakıt alımı"], correctAnswer: 2, explanation: "Kritik ekipmanın seyirde durdurulması riskli olduğundan liman veya demir süreleri değerlendirilir.", category: "Bakım" },
    { id: 117, question: "Bakım sırasında yedek ekipmanın devrede tutulmasının gerekçesi nedir?", options: ["Gürültü", "Isı", "Enerji tüketimi", "İşlevin kesintiye uğramaması ve emniyetin sürdürülmesi"], correctAnswer: 3, explanation: "Örneğin bir yağ pompası bakımdayken diğerinin çalışır ve otomatik devrede olması sağlanır.", category: "Bakım" },
    { id: 118, question: "Makine dairesinde temizlik ve düzenin (housekeeping) bakım üzerindeki etkisi nedir?", options: ["Sızıntı ve anormalliklerin erken fark edilmesini sağlaması", "Maliyet artışı", "Zaman kaybı", "Yalnızca estetik"], correctAnswer: 0, explanation: "Temiz zeminde yeni bir damla hemen görülür; kirli ortamda kaçak günlerce fark edilmez.", category: "Bakım" },
    { id: 119, question: "Bakım ekibinde görev dağılımının açık yapılmasının önemi nedir?", options: ["Maliyet için", "Hiyerarşi için", "Adımların atlanmaması ve emniyet sorumluluğunun belirli olması için", "Kayıt için"], correctAnswer: 2, explanation: "Toolbox talk ile roller, tehlikeler ve acil durum planı paylaşılır.", category: "Bakım" },
    { id: 120, question: "Bakım sonrası fonksiyon testinin yapılmadan işin kapatılması neden sakıncalıdır?", options: ["Maliyet", "Personel", "Kayıt eksikliği", "Ekipmanın gerçekten çalıştığının doğrulanmamış olması"], correctAnswer: 3, explanation: "Özellikle emniyet cihazlarında test edilmemiş bir onarım, arızanın kritik anda ortaya çıkmasına yol açar.", category: "Bakım" },
    { id: 121, question: "Emniyet valflerinin periyodik testinin kaydedilmesi neden gereklidir?", options: ["Maliyet takibi", "Ayar basıncında açtığının kanıtlanması ve klas gerekliliği", "Stok takibi", "Personel takibi"], correctAnswer: 1, explanation: "Test edilmemiş emniyet valfi, sistemin son korumasının belirsiz olması demektir.", category: "Bakım" },
    { id: 122, question: "Basınçlı kapların periyodik muayenesinde ne yapılır?", options: ["Yalnızca temizlik", "Yalnızca etiketleme", "Yalnızca boyama", "İç muayene, kalınlık ölçümü ve gerekiyorsa hidrostatik test"], correctAnswer: 3, explanation: "Hava tüpleri ve kazanlar klas programına göre muayene edilir; sonuçlar sertifikaya işlenir.", category: "Bakım" },
    { id: 123, question: "Hidrostatik testin pnömatik teste tercih edilmesinin nedeni nedir?", options: ["Daha hassas olması", "Daha hızlı olması", "Sıvının sıkışmaması nedeniyle ani boşalmada enerji açığa çıkmaması", "Daha ucuz olması"], correctAnswer: 2, explanation: "Basınçlı gazla test, kap patlarsa çok yüksek enerji açığa çıkarır ve ölümcül olabilir.", category: "Bakım" },
    { id: 124, question: "Boru hatlarında kalınlık ölçüm noktalarının haritalanması neyi sağlar?", options: ["Maliyet", "Hız", "Estetik", "Aynı noktaların zaman içinde karşılaştırılabilmesi"], correctAnswer: 3, explanation: "Farklı noktalardan alınan ölçümler eğilim vermez; sabit noktalar korozyon hızını gösterir.", category: "Bakım" },
    { id: 125, question: "Deniz suyu borularında en yaygın hasar mekanizması nedir?", options: ["Korozyon ve erozyon-korozyon", "Aşırı yük", "Titreşim", "Yorulma"], correctAnswer: 0, explanation: "Yüksek akış hızı ve dirsek bölgelerinde erozyon hızlanır; malzeme seçimi ve hız sınırı önemlidir.", category: "Bakım" },
    { id: 126, question: "Boru dirseklerinde aşınmanın daha hızlı olmasının nedeni nedir?", options: ["Daha sıcak olması", "Daha uzun olması", "Daha ince olması", "Akış yönü değişimiyle yerel hız ve türbülansın artması"], correctAnswer: 3, explanation: "Bu yüzden kalınlık ölçümlerinde dirsek dış yayları öncelikli kontrol noktalarıdır.", category: "Bakım" },
    { id: 127, question: "Bakım sırasında sökülen boruların uçlarının kapatılmasının nedeni nedir?", options: ["Sıcaklık korumak", "Estetik", "Sisteme kir ve yabancı cisim girmesini önlemek", "Basınç korumak"], correctAnswer: 2, explanation: "Özellikle hidrolik ve yağlama sistemlerinde küçük bir partikül dahi ciddi arıza yaratabilir.", category: "Bakım" },
    { id: 128, question: "Yağlama sistemi bakımından sonra sistemin yıkanmasının (flushing) amacı nedir?", options: ["Montaj kalıntılarını ve partikülleri sistemden uzaklaştırmak", "Isıtmak", "Basınç artırmak", "Soğutmak"], correctAnswer: 0, explanation: "Yıkama filtreleri ile temizlik seviyesi doğrulanmadan sistem devreye alınmamalıdır.", category: "Bakım" },
    { id: 129, question: "Filtre elemanlarının kirlilik durumunun izlenmesinde en pratik gösterge nedir?", options: ["Ağırlık", "Sıcaklık", "Renk", "Diferansiyel basınç"], correctAnswer: 3, explanation: "Fark basıncı arttıkça filtre tıkanmıştır; bypass açılmadan temizlenmeli veya değiştirilmelidir.", category: "Bakım" },
    { id: 130, question: "Filtre bypass valfinin açılması neyi gösterir?", options: ["Yüksek verimi", "Düşük basıncı", "Normal çalışmayı", "Filtrelenmemiş akışkanın sisteme gittiğini"], correctAnswer: 3, explanation: "Bypass koruma amaçlıdır ancak ekipman kirli akışkanla çalışır; kalıcı çözüm filtrenin bakımıdır.", category: "Bakım" },
    { id: 131, question: "Bakım için kullanılan kaldırma donanımının periyodik muayenesi neden zorunludur?", options: ["Maliyet için", "Kayıt için", "Yük altında kopma riskinin önlenmesi için", "Ağırlık için"], correctAnswer: 2, explanation: "Caraskal, sapan ve mapaların muayene ve testi kaldırma donanımı defterine işlenir.", category: "Bakım" },
    { id: 132, question: "Makine dairesinde ağır parça kaldırılırken hangi bilgi kritiktir?", options: ["Parça yaşı", "Parça markası", "Parça rengi", "Parçanın ağırlığı ile mapanın ve caraskalın kapasitesi"], correctAnswer: 3, explanation: "Kapasitesi aşılan bir mapa sökülüp fırlayabilir; yük yolunun altında personel bulunmaz.", category: "Bakım" },
    { id: 133, question: "Bakım planlamasında 'yedeklilik' kavramı neyi sağlar?", options: ["Maliyet artışı", "Bir ekipman bakımdayken işlevin sürdürülebilmesi", "Personel azaltma", "Hız artışı"], correctAnswer: 1, explanation: "Yedeği olmayan kritik ekipmanın bakımı, gemi emniyetini doğrudan etkilediğinden özel planlama gerektirir.", category: "Bakım" },
    { id: 134, question: "Klas onaylı bakım programına (PMS scheme) geçilmesinin faydası nedir?", options: ["Sörvey kredilerinin gemide yapılan bakımla karşılanabilmesi", "Maliyet artışı", "Kayıt azalması", "Bakım gerektirmemesi"], correctAnswer: 0, explanation: "Programın onaylı olması, kayıtların düzenli ve doğrulanabilir tutulmasını gerektirir.", category: "Bakım" },
    { id: 135, question: "Bakım yazılımında (CMMS) verilerin güncel tutulmamasının sonucu nedir?", options: ["Maliyet düşüşü", "Stok artışı", "Hız kaybı", "Planlamanın gerçeği yansıtmaması ve denetimde uygunsuzluk"], correctAnswer: 3, explanation: "Yapılmış ama kaydedilmemiş bakım, denetimde yapılmamış sayılır.", category: "Bakım" },
    { id: 136, question: "Bakım bütçesinin planlanmasında en büyük belirsizlik kaynağı nedir?", options: ["Liman ücreti", "Yakıt fiyatı", "Beklenmeyen arızalar ve acil yedek parça tedariki", "Personel maaşı"], correctAnswer: 2, explanation: "İyi işleyen önleyici bakım, bu belirsizliği ve toplam maliyeti belirgin biçimde azaltır.", category: "Bakım" },
    { id: 137, question: "Bakım ile enerji verimliliği arasındaki ilişki nedir?", options: ["Bakım tüketimi artırır", "Yalnızca maliyet ilişkisi vardır", "İlişkisizdir", "Bakımsız ekipman daha fazla enerji tüketir ve performansı düşer"], correctAnswer: 3, explanation: "Kirli eşanjör, aşınmış pompa ve kirli turbo doğrudan yakıt tüketimini artırır.", category: "Bakım" },
    { id: 138, question: "Gemi teslim alınırken (takeover) makine ekibinin öncelikli işi nedir?", options: ["Kritik ekipmanın durumunu, açık işleri ve yedek parça envanterini doğrulamak", "Personel tanışması", "Yakıt ölçümü", "Boya kontrolü"], correctAnswer: 0, explanation: "Devir listesi ve açık iş emirleri, sorumluluk sınırını ve öncelikleri belirler.", category: "Bakım" },
    { id: 139, question: "Baş mühendis değişiminde devir teslim raporunun kapsaması gereken temel konu nedir?", options: ["Yemek listesi", "Liman planı", "Personel izinleri", "Ekipman durumu, açık uygunsuzluklar, sörvey durumu ve kritik yedekler"], correctAnswer: 3, explanation: "Yazılı devir raporu, bilgi kaybını önleyen en etkili araçtır.", category: "Bakım" },
    { id: 140, question: "Bakım işlerinde fotoğraf ve ölçüm kaydı tutulmasının faydası nedir?", options: ["Hız", "Estetik", "Sonraki bakımlarda karşılaştırma ve klas/sigorta için kanıt", "Maliyet"], correctAnswer: 2, explanation: "Görsel kayıt, uzaktan teknik destek alınmasını da kolaylaştırır.", category: "Bakım" },
    { id: 141, question: "Uzaktan teknik destek (remote support) kullanımının bakımdaki yeri nedir?", options: ["Parça gönderir", "Yerine geçer", "Karmaşık arızalarda üretici uzmanlığına hızlı erişim sağlar", "Kayıt tutar"], correctAnswer: 2, explanation: "Veri paylaşımı ve görüntülü destek, servis bekleme süresini kısaltır.", category: "Bakım" },
    { id: 142, question: "Bakım stratejisinde 'run to failure' hangi ekipman için kabul edilebilir?", options: ["Dümen makinesi", "Yangın pompası", "Ana makine", "Yedeği bulunan, arızası sonuç doğurmayan basit ekipman"], correctAnswer: 3, explanation: "Örneğin kamara aydınlatması; kritik ekipmanda bu strateji kabul edilemez.", category: "Bakım" },
    { id: 143, question: "Bakım aralıklarının uzatılması hangi koşulda savunulabilir?", options: ["Durum izleme verisinin ekipmanın iyi durumda olduğunu göstermesi", "Personel eksikliği", "Zaman darlığı", "Maliyet baskısı"], correctAnswer: 0, explanation: "Veriye dayanmayan uzatma, ISM ve klas açısından kabul edilmez.", category: "Bakım" },
    { id: 144, question: "Bakımda kullanılan kimyasalların güvenlik bilgi formunun (SDS) okunması neden zorunludur?", options: ["Stok için", "Kayıt için", "Tehlikelerin, gerekli KKD'nin ve ilk yardımın öğrenilmesi için", "Maliyet için"], correctAnswer: 2, explanation: "Yanlış kimyasal kullanımı hem sağlık hem ekipman açısından ciddi zarar verebilir.", category: "Bakım" },
    { id: 145, question: "Bakım atıklarının (yağlı bez, filtre, kimyasal ambalaj) yönetimi nasıl olmalıdır?", options: ["Yakılır", "Depolanır", "Denize atılır", "Kategorilere ayrılıp kıyı tesisine teslim edilir ve kayda geçirilir"], correctAnswer: 3, explanation: "Bu atıklar MARPOL kapsamındadır; teslim makbuzları ilgili kayıt defterine işlenir.", category: "Bakım" },
    { id: 146, question: "Bakım sırasında ortaya çıkan asbest şüphesinde ne yapılmalıdır?", options: ["Çalışmaya devam edilir", "İş durdurulur, alan izole edilir ve IHM/uzman değerlendirmesi istenir", "Maskesiz sökülür", "Denize atılır"], correctAnswer: 1, explanation: "Asbest lifleri ciddi sağlık riskidir; gemide tehlikeli madde envanteri (IHM) bu bilgiyi içermelidir.", category: "Bakım" },
    { id: 147, question: "Bakım işlerinde yorgunluğun etkisi nedir?", options: ["Hızı artırır", "Maliyeti düşürür", "Etkisizdir", "Dikkat ve karar kalitesini düşürerek hata ve kaza olasılığını artırır"], correctAnswer: 3, explanation: "Uzun ve kritik bakımlar dinlenme sürelerine uygun planlanmalıdır.", category: "Bakım" },
    { id: 148, question: "Bakım kalitesinin ölçülmesinde hangi gösterge kullanılır?", options: ["Personel sayısı", "Harcanan saat", "Planlı bakım tamamlanma oranı ve arızalar arası ortalama süre (MTBF)", "Yedek parça sayısı"], correctAnswer: 2, explanation: "MTBF yükseliyor ve geciken görev oranı düşüyorsa bakım sistemi etkin çalışıyordur.", category: "Bakım" },
    { id: 149, question: "MTBF'nin (arızalar arası ortalama süre) artması neyi gösterir?", options: ["Maliyetin arttığını", "Bakımın azaldığını", "Arızaların arttığını", "Ekipman güvenilirliğinin iyileştiğini"], correctAnswer: 3, explanation: "Yanında MTTR (ortalama onarım süresi) da izlenerek toplam kullanılabilirlik değerlendirilir.", category: "Bakım" },
    { id: 150, question: "İyi bir bakım kültürünün en belirgin göstergesi nedir?", options: ["Küçük sapmaların arızaya dönüşmeden raporlanıp giderilmesi", "Fazla personel", "Yüksek bütçe", "Yeni ekipman"], correctAnswer: 0, explanation: "Sızıntı, ses veya sıcaklık değişimi gibi küçük belirtilerin ciddiye alındığı ortamda büyük arıza nadirdir.", category: "Bakım" },
  ],
  erm: [
    { id: 51, question: "Makine dairesi kaynak yönetiminin (ERM) temel amacı nedir?", options: ["Yakıt tasarrufu", "Bakım maliyetini düşürmek", "Personel sayısını azaltmak", "Mevcut insan, ekipman ve bilgi kaynaklarını emniyetli ve etkin biçimde kullanmak"], correctAnswer: 3, explanation: "STCW, ERM'yi mühendis yeterlilikleri arasında sayar; teknik bilgi kadar ekip becerileri de değerlendirilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 52, question: "Durumsal farkındalık (situational awareness) nasıl tanımlanır?", options: ["Hızlı çalışmak", "Alarmları duymak", "Mevcut durumu algılamak, anlamlandırmak ve yakın geleceği öngörmek", "Prosedürü ezberlemek"], correctAnswer: 2, explanation: "Üç seviyesi vardır: algılama, kavrama, öngörü. En kritik kayıp genellikle öngörü seviyesinde yaşanır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 53, question: "Durumsal farkındalık kaybının tipik belirtisi nedir?", options: ["Belirsizliklerin ve alarmların göz ardı edilmesi", "Kontrol listesi kullanımı", "Ekip içi tartışma", "Fazla soru sorulması"], correctAnswer: 0, explanation: "Açıklanamayan bir gösterge veya alarmın 'sonra bakarız' denerek geçilmesi klasik uyarı işaretidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 54, question: "Kapalı döngü iletişim (closed-loop communication) neyi sağlar?", options: ["Daha az konuşmayı", "Kayıt tutmayı", "Daha hızlı konuşmayı", "Mesajın alındığının ve doğru anlaşıldığının teyit edilmesini"], correctAnswer: 3, explanation: "Gönderen mesajı verir, alan tekrarlar, gönderen doğrular; gürültülü makine dairesinde hayati önemdedir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 55, question: "Makine dairesinde iletişim hatalarının en yaygın nedeni nedir?", options: ["Personel sayısı", "Vardiya süresi", "Telsiz arızası", "Gürültü, dil farkı ve varsayıma dayalı eksik mesajlar"], correctAnswer: 3, explanation: "Standart terminoloji ve teyit alışkanlığı bu riski belirgin biçimde azaltır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 56, question: "Çok uluslu ekiplerde ortak çalışma dilinin belirlenmesinin gerekçesi nedir?", options: ["Kayıt", "Yasal zorunluluk yok", "Acil durumda talimatların herkes tarafından anlaşılabilmesi", "Maliyet"], correctAnswer: 2, explanation: "SOLAS ve STCW, gemide anlaşılan ortak bir çalışma dili bulunmasını gerektirir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 57, question: "'Challenge and response' kültürü ne anlama gelir?", options: ["Sadece kaptanın soru sorması", "Yazılı itiraz", "Amirin sorgulanamaması", "Kıdemden bağımsız olarak herkesin şüpheli bir uygulamayı sorgulayabilmesi"], correctAnswer: 3, explanation: "Sorgulanan kişinin de savunmaya geçmeden net yanıt vermesi bu kültürün ikinci yarısıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 58, question: "Yüksek güç mesafesi (power distance) olan ekiplerde hangi risk artar?", options: ["Aşırı iletişim", "Astın hatayı fark etse dahi dile getirmemesi", "Fazla sorgulama", "Görev karmaşası"], correctAnswer: 1, explanation: "Liderin açıkça geri bildirim istemesi ve hatayı cezalandırmaması bu riski azaltır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 59, question: "Girişkenlik (assertiveness) ERM'de neyi ifade eder?", options: ["Endişeyi saygılı fakat net biçimde, gerekiyorsa ısrarla dile getirmek", "Sessiz kalmak", "Emir vermek", "Agresif davranmak"], correctAnswer: 0, explanation: "PACE (Probe-Alert-Challenge-Emergency) gibi kademeli yaklaşım, endişenin dikkate alınmasını sağlar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 60, question: "İş öncesi brifing (toolbox talk) neyi kapsamalıdır?", options: ["Yalnızca süre", "Yalnızca maliyet", "Yalnızca görev listesi", "Görev dağılımı, tehlikeler, KKD, iletişim yöntemi ve acil durum planı"], correctAnswer: 3, explanation: "Ortak zihinsel model oluşturulur; herkes ne yapacağını ve sapma hâlinde nasıl davranacağını bilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 61, question: "İş sonrası değerlendirme (debriefing) neden yapılır?", options: ["Zaman doldurmak", "Sorumluyu bulmak", "Neyin iyi gittiğini ve nelerin iyileştirilebileceğini paylaşarak öğrenmek", "Kayıt tutmak"], correctAnswer: 2, explanation: "Kısa ve suçlayıcı olmayan değerlendirme, ekip performansını sürekli iyileştiren en pratik araçtır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 62, question: "'Hata zinciri' (error chain) kavramı neyi anlatır?", options: ["Ekipman arızasını", "Personel eksikliğini", "Tek bir büyük hatayı", "Kazaların genellikle birbirini izleyen küçük hataların birikmesiyle oluştuğunu"], correctAnswer: 3, explanation: "Zincirin herhangi bir halkasını kırmak kazayı önler; ERM'nin amacı bu halkaları erken fark etmektir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 63, question: "İsviçre peyniri (Swiss cheese) modeli neyi açıklar?", options: ["Savunma katmanlarındaki boşlukların hizalanmasıyla kazanın oluşmasını", "Yakıt tüketimini", "Vardiya düzenini", "Bakım aralıklarını"], correctAnswer: 0, explanation: "Tek bir savunma katmanına güvenilemez; birden çok bağımsız bariyer gerekir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 64, question: "'Aktif hata' ile 'gizli koşul' arasındaki fark nedir?", options: ["Gizli koşul hemen sonuç verir", "Aktif hata sonuç doğurmaz", "Aynıdır", "Aktif hata sahada anında sonuç doğurur, gizli koşul sistemde uzun süre bekler"], correctAnswer: 3, explanation: "Yetersiz eğitim, kötü tasarım ve baskı gibi gizli koşullar, aktif hataların ortaya çıkmasını kolaylaştırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 65, question: "Ramak kala (near miss) bildirimlerinin ERM açısından değeri nedir?", options: ["Maliyet takibi", "İstatistik", "Kaza olmadan sistemdeki zayıflıkların görülmesini sağlaması", "Personel değerlendirmesi"], correctAnswer: 2, explanation: "Suçlayıcı olmayan raporlama kültürü olmadan bu veri toplanamaz ve öğrenme durur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 66, question: "Cezalandırıcı yaklaşımın raporlama üzerindeki etkisi nedir?", options: ["Kalitesini artırır", "Raporlamayı artırır", "Raporlamayı durdurur ve tehlikeleri görünmez kılar", "Etkisizdir"], correctAnswer: 2, explanation: "Adil kültür (just culture); kasıt ve pervasızlığı ayırırken dürüst hataları öğrenme fırsatı sayar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 67, question: "İş yükü yönetiminde (workload management) temel ilke nedir?", options: ["En hızlı kişinin çalışması", "Amirin tüm işi yapması", "Herkesin aynı işi yapması", "Görevlerin önceliklendirilip uygun kişilere dağıtılması"], correctAnswer: 3, explanation: "Aşırı yük kadar aşırı düşük yük de dikkat kaybı yaratır; denge gözetilmelidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 68, question: "Aşırı iş yükü altında en sık görülen hata türü nedir?", options: ["Adım atlama ve önemli bilgiyi gözden kaçırma", "Aşırı iletişim", "Fazla belgeleme", "Fazla kontrol"], correctAnswer: 0, explanation: "Kontrol listeleri, bu koşulda hafızaya güvenmeyi önleyen en etkili araçtır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 69, question: "Görev delege ederken en kritik nokta nedir?", options: ["Kıdeme göre vermek", "Hızlı devretmek", "Kişinin yetkinliğini doğrulamak ve beklentiyi açıkça tanımlamak", "Yazılı yapmak"], correctAnswer: 2, explanation: "Delegasyon sorumluluğu ortadan kaldırmaz; izleme ve geri bildirim sürdürülür.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 70, question: "Acil durumda karar verme sürecinde ilk adım nedir?", options: ["Rapor yazmak", "Ekip toplamak", "Hemen müdahale", "Durumu hızlıca değerlendirip önceliği belirlemek"], correctAnswer: 3, explanation: "Hatalı teşhise dayanan hızlı müdahale, durumu ağırlaştırabilir; birkaç saniyelik değerlendirme değerlidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 71, question: "Acil durumda önceliklendirmede genel sıralama nasıldır?", options: ["Ekipman, çevre, insan", "İnsan hayatı, gemi emniyeti, çevre, mal", "Çevre, insan, gemi", "Mal, insan, çevre"], correctAnswer: 1, explanation: "Bu sıralama tüm acil durum planlarının temelini oluşturur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 72, question: "'Tünel görüşü' (tunnel vision) ne anlama gelir?", options: ["Hızlı karar", "Ekip çalışması", "Geniş bakış açısı", "Tek bir soruna odaklanıp diğer kritik göstergeleri kaçırmak"], correctAnswer: 3, explanation: "Stres altında yaygındır; ekip üyelerinin genel durumu izlemesi bu riski dengeler.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 73, question: "Stresin karar verme üzerindeki etkisi nedir?", options: ["Yalnızca hızı artırır", "Her zaman iyileştirir", "Belirli bir düzeye kadar performansı artırır, sonrasında bozar", "Etkisizdir"], correctAnswer: 2, explanation: "Yerkes-Dodson ilişkisi: aşırı uyarılma dikkat alanını daraltır ve hata olasılığını yükseltir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 74, question: "Yorgunluğun ERM açısından en tehlikeli etkisi nedir?", options: ["İştahsızlık", "Uykusuzluk", "Kas ağrısı", "Kişinin performans düşüşünün farkında olmaması"], correctAnswer: 3, explanation: "Yorgun kişi kendi durumunu doğru değerlendiremez; bu yüzden dinlenme kuralları nesnel biçimde uygulanmalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 75, question: "STCW'ye göre herhangi bir 24 saatlik dönemde asgari dinlenme süresi kaç saattir?", options: ["10 saat", "12 saat", "14 saat", "8 saat"], correctAnswer: 0, explanation: "En çok iki parçaya bölünebilir ve bir bölüm en az 6 saat olmalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 76, question: "STCW'ye göre 7 günlük dönemde asgari toplam dinlenme kaç saattir?", options: ["84 saat", "56 saat", "70 saat", "77 saat"], correctAnswer: 3, explanation: "Manila değişiklikleriyle belirlenen bu sınır, kayıtlarla belgelenir ve denetlenir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 77, question: "Dinlenme saati kayıtlarının gerçeği yansıtmaması hangi sonucu doğurur?", options: ["Personel memnuniyeti", "Sadece idari uyarı", "ISM/MLC uygunsuzluğu ve yorgunluk kaynaklı kaza riskinin gizlenmesi", "Maliyet artışı"], correctAnswer: 2, explanation: "Kâğıt üzerinde uygun görünen kayıtlar, gerçek riski yönetilemez hâle getirir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 78, question: "Vardiya devrinde (handover) devralanın sorumluluğu nedir?", options: ["Sistem durumunu, açık işleri ve kısıtları anlayıp teyit ettikten sonra devralmak", "Yalnızca imzalamak", "Yalnızca dinlemek", "Hemen devralmak"], correctAnswer: 0, explanation: "Anlaşılmayan nokta kalırsa devir tamamlanmaz; kritik bir manevra sırasında devir yapılmaz.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 79, question: "Devir teslimde yazılı not kullanmanın faydası nedir?", options: ["Kayıt zorunluluğu", "Maliyet", "Zaman kazandırır", "Sözlü aktarımdaki unutma ve yanlış anlaşılmayı azaltır"], correctAnswer: 3, explanation: "Özellikle devre dışı ekipman ve süregelen izinler yazılı olarak aktarılmalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 80, question: "Köprüüstü ile makine dairesi arasındaki koordinasyonun kritik olduğu durum hangisidir?", options: ["Demirde bekleme", "Liman beklemesi", "Rutin seyir", "Manevra, yakıt değişimi ve acil durumlar"], correctAnswer: 3, explanation: "Manevra öncesi bildirim süresi, makinenin hazırlık gereksinimine göre belirlenir ve uyulur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 81, question: "Manevra öncesi köprüüstünün makine dairesine önceden haber vermesinin gerekçesi nedir?", options: ["Yakıt hesabı", "Nezaket", "Makinenin ısınma, yağlama ve yardımcı sistem hazırlığını tamamlayabilmesi", "Kayıt"], correctAnswer: 2, explanation: "Yetersiz hazırlık, manevrada güç kaybı riskini artırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 82, question: "Otomasyona aşırı güvenin (complacency) ERM'deki riski nedir?", options: ["Enerji kaybı", "Maliyet", "Hız kaybı", "Sistemin sorgulanmaması ve sapmanın geç fark edilmesi"], correctAnswer: 3, explanation: "Düzenli tur kontrolleri ve manuel doğrulama, otomasyonun kör noktalarını kapatır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 83, question: "Ekip içinde 'ortak zihinsel model' oluşturmanın faydası nedir?", options: ["Daha az konuşma", "Herkesin aynı durumu ve planı anlamasıyla koordinasyonun kolaylaşması", "Daha hızlı iş", "Daha az kayıt"], correctAnswer: 1, explanation: "Brifing ve düzenli bilgi paylaşımı bu modeli kurar ve günceller.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 84, question: "Liderlik ERM'de neyi gerektirir?", options: ["Görev dağıtmak, izlemek, geri bildirim vermek ve karar sorumluluğunu üstlenmek", "Sessiz kalmak", "Yalnızca denetlemek", "Tüm işi kendi yapmak"], correctAnswer: 0, explanation: "İyi lider, ekipten bilgi akışını teşvik eder ve kendi kararını da sorgulanabilir kılar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 85, question: "Ekipte yeni ve deneyimsiz bir üye varsa lider ne yapmalıdır?", options: ["Yalnız çalıştırmalı", "Kayıt tutmalı", "Görev vermemeli", "Görevi netleştirip yakın gözetim ve geri bildirim sağlamalı"], correctAnswer: 3, explanation: "Yetkinlik seviyesine göre denetim yoğunluğu ayarlanır; bu, hem öğrenmeyi hem emniyeti destekler.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 86, question: "Ekip içinde çatışma yönetiminde doğru yaklaşım nedir?", options: ["Yazılı şikâyet", "Görmezden gelmek", "Kişiyi değil sorunu ele alarak ortak çözüm aramak", "Kıdeme göre karar"], correctAnswer: 2, explanation: "Çözülmemiş çatışma, kritik bilginin paylaşılmamasına ve emniyetin zayıflamasına yol açar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 87, question: "Kontrol listelerinin (checklist) ERM'deki rolü nedir?", options: ["Kayıt tutmak", "Zaman doldurmak", "Bürokrasi", "Hafızaya bağımlılığı azaltarak kritik adımların atlanmasını önlemek"], correctAnswer: 3, explanation: "Etkili kullanım için listenin okunup uygulanması gerekir; sonradan toplu imzalanan liste işlevsizdir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 88, question: "Kontrol listesinin 'sonradan doldurulması' neden sakıncalıdır?", options: ["Adımların gerçekten yapıldığının doğrulanmamış olması", "Zaman kaybı", "Maliyet", "Kayıt hatası"], correctAnswer: 0, explanation: "Bu alışkanlık, listenin sağladığı bariyeri tamamen ortadan kaldırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 89, question: "Prosedürden sapma gerektiğinde doğru davranış nedir?", options: ["Prosedürü değiştirmek", "İşi iptal etmek", "Sessizce sapmak", "Riski değerlendirip yetkiliye danışmak ve kararı kayda geçirmek"], correctAnswer: 3, explanation: "Belgelenmemiş sapmalar, normalleşerek kalıcı bir risk hâline gelir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 90, question: "'Sapmanın normalleşmesi' (normalization of deviance) ne demektir?", options: ["Ekipman arızası", "Prosedürün güncellenmesi", "Kural dışı uygulamanın sonuç doğurmadıkça kabul edilir hâle gelmesi", "Eğitim eksikliği"], correctAnswer: 2, explanation: "Birçok büyük kazanın öncesinde uzun süredir sürdürülen bu tür uygulamalar bulunur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 91, question: "Ticari baskı altında emniyet kararı verirken temel ilke nedir?", options: ["Hızlı bitirmek", "Programa uymak", "Emniyetin ticari kaygının önünde tutulması ve kararın gerekçelendirilmesi", "Maliyeti düşürmek"], correctAnswer: 2, explanation: "ISM, kaptana ve baş mühendise emniyet gerektirdiğinde karar alma yetkisini açıkça verir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 92, question: "Baş mühendisin şirketten destek istemesi hangi durumda uygundur?", options: ["Yalnızca arızada", "Yalnızca limanda", "Hiçbir zaman", "Kaynak, uzmanlık veya karar desteği gerektiğinde"], correctAnswer: 3, explanation: "Destek istemek zayıflık değil, risk yönetiminin parçasıdır; DPA bu iletişimin bir kanalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 93, question: "DPA'nın (Designated Person Ashore) ERM açısından işlevi nedir?", options: ["Gemi ile üst yönetim arasında ticari baskıdan bağımsız bir emniyet kanalı sağlamak", "Yakıt almak", "Personel atamak", "Bakım planlamak"], correctAnswer: 0, explanation: "DPA'nın üst yönetime doğrudan erişimi olması bu bağımsızlığın güvencesidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 94, question: "Acil durum tatbikatlarının ERM açısından kazandırdığı nedir?", options: ["Denetim", "Kayıt", "Rollerin otomatikleşmesi ve ekip koordinasyonunun test edilmesi", "Maliyet"], correctAnswer: 2, explanation: "Gerçek olayda düşünme süresi çok kısadır; tekrarlanan tatbikat tepki süresini kısaltır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 95, question: "Tatbikat sonrası değerlendirmede en değerli çıktı nedir?", options: ["Süre kaydı", "Fotoğraflar", "Katılım listesi", "Belirlenen eksiklikler ve bunlara atanan düzeltici faaliyetler"], correctAnswer: 3, explanation: "Aksaklıklar kayda geçirilip takip edilmezse aynı hatalar tekrarlanır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 96, question: "Blackout tatbikatının makine ekibi için önemi nedir?", options: ["Yakıt tasarrufu", "Toparlanma sırasının ve rollerin gerçek koşulda denenmesi", "Gürültü ölçümü", "Bakım planı"], correctAnswer: 1, explanation: "Acil jeneratör devreye girişi, kritik sistemlerin öncelik sırası ve köprüüstü koordinasyonu test edilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 97, question: "Makine dairesi yangın tatbikatında ERM açısından kritik unsur nedir?", options: ["Su miktarı", "Yangın türü", "Söndürücü sayısı", "Haberleşme, personel sayımı ve müdahale ile sınır soğutmanın koordinasyonu"], correctAnswer: 3, explanation: "Ekiplerin konumu ve hava süresi sürekli izlenmeli; köprüüstü ile bilgi akışı kesilmemelidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 98, question: "Kapalı mahal kurtarma tatbikatının önemi nedir?", options: ["Maliyet", "Kayıt tutmak", "Kurtarmaya giren ikinci kişinin de kurban olmasını önleyen prosedürün pekişmesi", "Süre ölçmek"], correctAnswer: 2, explanation: "Kapalı mahal ölümlerinin çoğu, plansız kurtarma girişimlerinde yaşanır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 99, question: "Yeni katılan mühendise verilen familiarization eğitiminin kapsamı ne olmalıdır?", options: ["Yalnızca vardiya saatleri", "Yalnızca yemek düzeni", "Yalnızca kamara", "Gemiye özgü sistemler, acil durum rolleri, kaçış yolları ve kritik prosedürler"], correctAnswer: 3, explanation: "Tamamlanmadan bağımsız vardiya verilmemelidir; kayıtları tutulur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 100, question: "Gemide sürekli eğitimin (onboard training) ERM'ye katkısı nedir?", options: ["Ekip yetkinliğini güncel tutarak hata olasılığını düşürmesi", "Maliyet", "Denetim", "Kayıt"], correctAnswer: 0, explanation: "Yeni ekipman ve prosedürler için eğitim, değişiklik yönetiminin ayrılmaz parçasıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 101, question: "'Değişiklik yönetimi' (management of change) neyi gerektirir?", options: ["Yalnızca onay", "Yalnızca kayıt", "Hızlı uygulama", "Değişikliğin risklerinin değerlendirilip eğitim ve dokümantasyonun güncellenmesi"], correctAnswer: 3, explanation: "Ekipman, prosedür veya personel değişimi yeni riskler doğurabilir; plansız değişim kaza kaynağıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 102, question: "Personel değişiminin yoğun olduğu dönemde hangi risk artar?", options: ["Alarm sayısı", "Yakıt tüketimi", "Gemiye özgü bilgi kaybı ve ekip uyumunun zayıflaması", "Bakım maliyeti"], correctAnswer: 2, explanation: "Devir raporları, familiarization ve yakın gözetim bu dönemde daha da kritik hâle gelir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 103, question: "İş emniyeti analizinin (JSA) ERM ile ilişkisi nedir?", options: ["İşi adımlara ayırarak tehlikeleri ve önlemleri ekiple birlikte belirlemesi", "Yalnızca kayıt", "Yalnızca maliyet", "İlişkisizdir"], correctAnswer: 0, explanation: "Analize işi yapacak kişilerin katılması, hem gerçekçilik hem sahiplenme sağlar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 104, question: "Risk değerlendirmesinde 'ALARP' ilkesi neyi ifade eder?", options: ["Riskin kabul edilmesini", "Riskin devredilmesini", "Riskin sıfırlanmasını", "Riskin makul biçimde uygulanabilir en düşük seviyeye indirilmesini"], correctAnswer: 3, explanation: "Sıfır risk çoğu zaman mümkün değildir; önlem maliyeti ile risk azalması dengelenir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 105, question: "Riskin 5×5 matriste 20 çıkması hangi kararı gerektirir?", options: ["İş iptal edilir", "İş ertelenir", "İş normal sürer", "İş, ek kontrol önlemleri alınmadan başlatılmaz"], correctAnswer: 3, explanation: "Yüksek risk bölgesinde önlem alınıp yeniden değerlendirme yapılır; kabul edilebilir seviyeye inmelidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 106, question: "Kontrol önlemleri hiyerarşisinde ERM açısından en zayıf halka hangisidir?", options: ["İkame", "Eleme", "Kişisel koruyucu donanım", "Mühendislik kontrolü"], correctAnswer: 2, explanation: "KKD tehlikeyi ortadan kaldırmaz ve doğru kullanıma bağlıdır; öncelik tehlikenin kaynağındadır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 107, question: "İzin sisteminin (permit to work) ERM'deki işlevi nedir?", options: ["Kayıt tutmak", "Yetki dağıtmak", "Bürokrasi", "Bağımsız bir kişinin hazırlıkları doğrulamasıyla ek bir savunma katmanı oluşturmak"], correctAnswer: 3, explanation: "İzni veren kişi kontrolleri bizzat doğrular; bu, tek kişiye bağımlılığı ortadan kaldırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 108, question: "İzin süresi dolduğunda çalışmaya devam edilmesi neden kabul edilemez?", options: ["Kayıt bozulur", "Koşullar değişmiş olabileceğinden yeniden değerlendirme yapılmamış olur", "Maliyet artar", "Zaman kaybı olur"], correctAnswer: 1, explanation: "Vardiya değişimi, hava koşulu veya operasyon değişikliği riski tamamen değiştirebilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 109, question: "Ekip üyesinin bir işi güvenli bulmaması hâlinde doğru davranış nedir?", options: ["İşi durdurma yetkisini (stop work authority) kullanmak", "Amire şikâyet etmek", "Sessiz kalmak", "İşi yapmak"], correctAnswer: 0, explanation: "Bu yetkinin kullanılması cezalandırılmamalı, aksine desteklenmelidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 110, question: "'Stop work authority' uygulamasının etkin olması neye bağlıdır?", options: ["Ceza sistemi", "Kayıt sistemi", "Yazılı prosedür", "Yönetimin bu yetkiyi kullananı desteklediğinin ekip tarafından bilinmesi"], correctAnswer: 3, explanation: "Bir kez olumsuz tepki verilmesi, yetkinin fiilen kullanılamaz hâle gelmesine yeter.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 111, question: "Makine dairesinde yalnız çalışmanın (lone working) yönetimi nasıl olmalıdır?", options: ["Yalnızca gündüz yapılır", "Serbesttir", "Bildirilmeli, düzenli teyit alınmalı ve dead man alarmı kullanılmalıdır", "Yasaktır"], correctAnswer: 2, explanation: "Bilinç kaybı hâlinde fark edilme süresi hayati önemdedir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 112, question: "Gürültülü ortamda iletişimde alınacak önlem nedir?", options: ["Yazışmak", "Beklemek", "Bağırmak", "Telsiz/kulaklık kullanmak, göz teması ve tekrar ile teyit almak"], correctAnswer: 3, explanation: "El işaretleri de önceden kararlaştırılabilir; teyit alınmadan işlem başlatılmaz.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 113, question: "Arıza gidermede ekip yaklaşımının bireysel yaklaşıma üstünlüğü nedir?", options: ["Farklı bakış açılarının doğrulama sağlaması ve tünel görüşünü kırması", "Daha ucuz olması", "Daha az kayıt", "Daha hızlı olması"], correctAnswer: 0, explanation: "Bir kişinin varsayımı, ekip içinde sorgulandığında hızla düzeltilebilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 114, question: "Arıza giderirken 'varsayımı doğrulama' alışkanlığı neden önemlidir?", options: ["Hız için", "Maliyet için", "Kayıt için", "Yanlış varsayımın uzun ve maliyetli yanlış aramaya yol açması nedeniyle"], correctAnswer: 3, explanation: "Her adımda ölçüm veya gözlemle doğrulama, arıza arama süresini belirgin biçimde kısaltır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 115, question: "Kaynakların (zaman, yedek parça, personel) sınırlı olduğu durumda karar ölçütü ne olmalıdır?", options: ["Kıdem", "Maliyet", "Emniyet ve geminin sevk kabiliyeti üzerindeki etki", "Kolaylık"], correctAnswer: 2, explanation: "Kritik ekipmana öncelik verilir; ertelenen işler risk değerlendirmesiyle belgelenir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 116, question: "Bilginin ekip içinde paylaşılmaması hangi riski yaratır?", options: ["Kayıt eksikliği", "Maliyet artışı", "Kritik bir kısıtın bilinmemesi nedeniyle hatalı karar", "Zaman kaybı"], correctAnswer: 2, explanation: "Örneğin devre dışı bir alarmın bilinmemesi, o sistemin korumasız olduğunun fark edilmemesine yol açar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 117, question: "Devre dışı bırakılan bir emniyet cihazının yönetimi nasıl olmalıdır?", options: ["Not tutulmaz", "Yalnızca baş mühendis bilir", "Sözlü bildirim yeterli", "Etiketlenmeli, kayda geçirilmeli, süre verilmeli ve tüm vardiyalara bildirilmelidir"], correctAnswer: 3, explanation: "Telafi edici önlemler tanımlanmadan devre dışı bırakma kabul edilemez.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 118, question: "ERM eğitiminin simülatörde yapılmasının faydası nedir?", options: ["Gerçek riske girmeden kriz koşullarında ekip davranışının denenmesi", "Kayıt kolaylığı", "Süre kısalığı", "Maliyet düşüklüğü"], correctAnswer: 0, explanation: "Simülatör, teknik beceriyle birlikte iletişim ve karar süreçlerini de değerlendirmeye imkân verir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 119, question: "Geri bildirim verirken etkili yaklaşım nedir?", options: ["Sessiz kalmak", "Genel eleştiri", "Somut davranışa odaklanmak ve iyileştirme önerisi sunmak", "Kişiliği eleştirmek"], correctAnswer: 2, explanation: "Zamanında ve yapıcı geri bildirim, davranış değişimini en çok destekleyen araçtır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 120, question: "Ekip performansının değerlendirilmesinde hangi gösterge daha anlamlıdır?", options: ["Arıza sayısı", "Yakıt tüketimi", "Kişisel hız", "Ramak kala bildirimi, tatbikat kalitesi ve prosedür uyumu gibi öncü göstergeler"], correctAnswer: 3, explanation: "Ardıl göstergeler geçmişi anlatır; öncü göstergeler gelecekteki riski azaltmaya imkân verir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 121, question: "Makine dairesinde 'iki kişi kuralı' hangi işlerde uygulanır?", options: ["Tüm işlerde", "Yüksek riskli işlerde (kapalı mahal, yüksekte çalışma, elektrik)", "Rutin turlarda", "Kayıt işlerinde"], correctAnswer: 1, explanation: "Karşılıklı gözetim, hem hatayı hem acil durumda müdahalesizliği önler.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 122, question: "Acil durumda rol karmaşasının önlenmesi nasıl sağlanır?", options: ["Amirin anlık yönlendirmesi", "Telsizle koordinasyon", "Herkesin serbest hareketi", "Muster listesi ve acil durum planında rollerin önceden tanımlanmasıyla"], correctAnswer: 3, explanation: "Önceden tanımlı roller, kriz anında karar yükünü azaltır ve boşluk kalmasını önler.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 123, question: "Kriz anında liderin en önemli davranışı nedir?", options: ["Rapor yazmak", "Her işi üstlenmek", "Sakin kalmak, öncelik belirlemek ve net görev dağıtmak", "Sessiz kalmak"], correctAnswer: 2, explanation: "Liderin paniği ekibe hızla yayılır; net ve kısa talimatlar koordinasyonu korur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 124, question: "Bilgi aşırı yüklenmesi (information overload) durumunda ne yapılmalıdır?", options: ["Alarmları kapatmak", "Ekranı kapatmak", "Tüm veriyi izlemek", "Kritik parametrelere odaklanıp ikincil bilgileri filtrelemek"], correctAnswer: 3, explanation: "Alarm önceliklendirmesi ve görev dağılımı, bilişsel yükü ekip içinde paylaştırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 125, question: "Kritik bir kararda 'ikinci görüş' almanın faydası nedir?", options: ["Kör noktaların ve varsayım hatalarının yakalanması", "Sorumluluk paylaşımı", "Kayıt oluşturma", "Zaman kazanma"], correctAnswer: 0, explanation: "Karar hâlâ liderindir; ancak farklı bakış açısı hatalı teşhisi erken ortaya çıkarır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 126, question: "Kültürel farklılıkların ERM'de yönetilmesi neden gereklidir?", options: ["Yemek düzeni için", "Vardiya için", "Sosyal uyum için", "İletişim biçimi ve otoriteye yaklaşımın emniyet davranışını etkilemesi nedeniyle"], correctAnswer: 3, explanation: "Açık iletişim normlarının ekipçe kararlaştırılması, kültürel farkın yarattığı riski azaltır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 127, question: "Gemide emniyet toplantılarının düzenli yapılmasının amacı nedir?", options: ["Maliyet", "Kayıt", "Bulguların, ramak kalaların ve düzeltici faaliyetlerin ekiple paylaşılması", "Personel değerlendirme"], correctAnswer: 2, explanation: "Toplantı tutanakları takip edilir; kapatılmayan aksiyonlar bir sonraki toplantıya taşınır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 128, question: "Diğer gemilerde yaşanan kazalardan öğrenmenin yolu nedir?", options: ["Kaza raporlarını ve emniyet bültenlerini ekiple değerlendirmek", "Yalnızca arşivlemek", "Yalnızca kaptanın okuması", "Görmezden gelmek"], correctAnswer: 0, explanation: "Benzer koşulların kendi gemisinde bulunup bulunmadığının sorgulanması en değerli çıktıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 129, question: "Emniyet gözlem programlarının (behavioural safety) amacı nedir?", options: ["Kayıt üretmek", "Personel seçmek", "Ceza vermek", "Güvenli ve güvensiz davranışları gözlemleyip geri bildirimle davranışı iyileştirmek"], correctAnswer: 3, explanation: "Gözlem isimsiz ve yapıcı olmalıdır; amaç kişiyi değil davranış eğilimini değiştirmektir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 130, question: "Makine dairesi turlarının belirli bir rota ve sırayla yapılmasının faydası nedir?", options: ["Yakıt tasarrufu", "Kayıt kolaylığı", "Süre kısalır", "Hiçbir bölgenin ve ekipmanın atlanmaması"], correctAnswer: 3, explanation: "Sistematik tur, dikkatin dağıldığı durumlarda dahi kapsamı korur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 131, question: "Tur sırasında fark edilen küçük bir sızıntının hemen raporlanmasının gerekçesi nedir?", options: ["Personel değerlendirmesi", "Kayıt zorunluluğu", "Küçük belirtilerin büyük arıza ve yangının öncüsü olabilmesi", "Maliyet takibi"], correctAnswer: 2, explanation: "Basınçlı yakıt sızıntısı makine dairesi yangınlarının bilinen en yaygın başlangıcıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 132, question: "Ekip içinde 'ben hallederim' tutumunun riski nedir?", options: ["Maliyet", "Kayıt eksikliği", "Hız kaybı", "Bilginin paylaşılmaması ve gerektiğinde destek alınamaması"], correctAnswer: 3, explanation: "Kaynak yönetimi, bireysel kahramanlık değil planlı ekip çalışması gerektirir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 133, question: "Bir mühendisin yetkinliğinin dışında bir işle karşılaşması hâlinde doğru davranış nedir?", options: ["Denemek", "Sınırını bildirip destek veya uzman görüşü istemek", "İşi ertelemek", "Görmezden gelmek"], correctAnswer: 1, explanation: "Yetkinlik sınırının farkında olmak, ERM'nin temel bireysel becerilerindendir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 134, question: "Uzun süren bakımlarda molaların planlanmasının gerekçesi nedir?", options: ["Dikkat ve konsantrasyonun korunarak hata olasılığının düşürülmesi", "Kayıt", "Maliyet", "Sosyal ihtiyaç"], correctAnswer: 0, explanation: "Kritik montaj adımları yorgun bir ekibe bırakılmamalı; gerekirse iş ertesi güne planlanmalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 135, question: "Gece vardiyasında performans düşüşünün nedeni nedir?", options: ["Sıcaklık", "Gürültü", "Aydınlatma", "Sirkadiyen ritim nedeniyle uyanıklığın doğal olarak azalması"], correctAnswer: 3, explanation: "Özellikle 03:00–05:00 arası en riskli dönemdir; kritik işler mümkünse bu saatlere planlanmaz.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 136, question: "Vardiya sistemi tasarlanırken ERM açısından neye dikkat edilmelidir?", options: ["Maliyet", "Eşit süre", "Yeterli kesintisiz dinlenme ve sirkadiyen uyum", "Kıdem sırası"], correctAnswer: 2, explanation: "Sık değişen vardiya düzeni uyum sağlamayı zorlaştırır ve kümülatif yorgunluk yaratır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 137, question: "Limanda yoğun iş yükünün yönetiminde temel yaklaşım nedir?", options: ["Bakımın ertelenmesi", "Personel artırımı", "Herkesin sürekli çalışması", "İşlerin önceliklendirilip dinlenme sürelerinin korunması"], correctAnswer: 3, explanation: "Liman dönemi yorgunluğun en çok biriktiği evredir; plan denize çıkış öncesini de kapsamalıdır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 138, question: "Sefer öncesi makine hazırlık planının ekiple paylaşılmasının faydası nedir?", options: ["Herkesin görevini ve zamanlamayı bilmesiyle eksik hazırlığın önlenmesi", "Maliyet", "Hız", "Kayıt"], correctAnswer: 0, explanation: "Eksik hazırlık, manevrada güç kaybı gibi ciddi sonuçlar doğurabilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 139, question: "Makine dairesi ile köprüüstü arasında ortak tatbikat yapılmasının değeri nedir?", options: ["Maliyet", "Süre", "Kayıt", "Arayüzdeki iletişim ve koordinasyon zayıflıklarının ortaya çıkması"], correctAnswer: 3, explanation: "Gerçek olaylarda en sık kopma, bu iki birim arasındaki bilgi akışında yaşanır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 140, question: "ERM'de 'kaynak' kavramı neleri kapsar?", options: ["Yalnızca zamanı", "Yalnızca personeli", "İnsan, ekipman, bilgi, zaman ve dış destek dahil tüm kaynakları", "Yalnızca ekipmanı"], correctAnswer: 2, explanation: "El kitapları, kıyı desteği ve üretici yardım hattı da yönetilmesi gereken kaynaklardır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 141, question: "El kitapları ve teknik dokümanların erişilebilir olmasının önemi nedir?", options: ["Kayıt", "Estetik", "Arıza anında doğru bilgiye hızla ulaşılabilmesi", "Denetim"], correctAnswer: 2, explanation: "Güncel olmayan veya bulunamayan doküman, arıza süresini ve yanlış müdahale riskini artırır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 142, question: "Karar verirken zaman baskısı hissedildiğinde önerilen yaklaşım nedir?", options: ["Kararı ertelemek", "Başkasına devretmek", "Hemen karar vermek", "Mümkünse kısa bir duraklamayla durumu yeniden değerlendirmek"], correctAnswer: 3, explanation: "Birkaç saniyelik bilinçli duraklama, hatalı teşhisin fark edilmesi için çoğu zaman yeterlidir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 143, question: "Acil durumda alınan kararların sonradan kaydedilmesinin amacı nedir?", options: ["Olayın incelenebilmesi ve dersler çıkarılabilmesi", "Maliyet", "Sigorta", "Suçlamak"], correctAnswer: 0, explanation: "Zaman damgalı kayıtlar hem hukuki hem teknik değerlendirmede birincil kaynaktır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 144, question: "'Alarm körlüğü' (alarm fatigue) nasıl önlenir?", options: ["Ekranı kapatarak", "Alarmları kapatarak", "Alarm sayısını ve önceliklerini düzenli gözden geçirerek", "Sesi kısarak"], correctAnswer: 2, explanation: "Sürekli çalan anlamsız alarmlar, gerçek alarmın da göz ardı edilmesine yol açar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 145, question: "Ekip üyelerinin birbirinin işini çapraz kontrol etmesi neyi sağlar?", options: ["Maliyet artışı", "Kayıt artışı", "Yavaşlama", "Tek kişiye bağlı hatanın yakalanması"], correctAnswer: 3, explanation: "Özellikle valf sıralaması ve elektrik izolasyonu gibi kritik adımlarda çapraz kontrol standarttır.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 146, question: "Valf işlemlerinde 'işaretleme ve teyit' uygulamasının gerekçesi nedir?", options: ["Kayıt", "Yanlış valfin açılması/kapanmasının ciddi sonuçlar doğurabilmesi", "Hız", "Maliyet"], correctAnswer: 1, explanation: "Etiketli valf listesi ve ikinci kişi teyidi, bu klasik hatayı büyük ölçüde önler.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 147, question: "Yakıt alma (bunkering) operasyonunda ERM açısından en kritik unsur nedir?", options: ["Maliyet", "Yakıt kalitesi", "Hız", "Görev dağılımı, sürekli iletişim ve acil durdurma sinyalinin önceden kararlaştırılması"], correctAnswer: 3, explanation: "İletişim kopması hâlinde operasyon derhal durdurulur; taşma ve kirlilik riski bu şekilde yönetilir.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 148, question: "Operasyon sırasında iletişim kesilirse doğru davranış nedir?", options: ["Yedek personel çağırmak", "Devam etmek", "Operasyonu durdurup iletişim yeniden kurulana kadar beklemek", "Hızlanmak"], correctAnswer: 2, explanation: "Kör operasyon, özellikle transfer işlemlerinde en yüksek risk koşuludur.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 149, question: "ERM becerilerinin teknik bilgiyle birlikte değerlendirilmesinin gerekçesi nedir?", options: ["Maliyet", "Kayıt", "Sınav gereği", "Kazaların büyük bölümünün teknik bilgi eksikliğinden değil, kaynak ve iletişim yönetiminden kaynaklanması"], correctAnswer: 3, explanation: "STCW yeterlilik değerlendirmesi bu yüzden hem teknik hem ekip becerilerini kapsar.", category: "Makine Dairesi Kaynak Yönetimi" },
    { id: 150, question: "Etkin bir ERM kültürünün en somut göstergesi nedir?", options: ["Ekibin sapmaları açıkça dile getirmesi ve endişelerin ciddiye alınması", "Yüksek hız", "Düşük maliyet", "Az sayıda rapor"], correctAnswer: 0, explanation: "Sessiz bir makine dairesi güvenli değil, çoğu zaman risklerin görünmez olduğu bir ortamdır.", category: "Makine Dairesi Kaynak Yönetimi" },
  ],
};
